INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (1,1,'Al-Faatiha','بِسۡمِ ٱللَّهِ ٱلرَّحۡمَٰنِ ٱلرَّحِيمِ','شروع الله کا نام لے کر جو بڑا مہربان نہایت رحم والا ہے','In the Name of Allah—the Most Compassionate, Most Merciful','अल्लाह के नाम से जो रहमान व रहीम है।');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (1,2,'Al-Faatiha','ٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ','سب طرح کی تعریف خدا ہی کو (سزاوار) ہے جو تمام مخلوقات کا پروردگار ہے','All praise is for Allah—Lord of all worlds','तारीफ़ अल्लाह ही के लिये है जो तमाम क़ायनात का रब है।');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (1,3,'Al-Faatiha','ٱلرَّحۡمَٰنِ ٱلرَّحِيمِ','بڑا مہربان نہایت رحم والا','the Most Compassionate, Most Merciful','रहमान और रहीम है।');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (1,4,'Al-Faatiha','مَٰلِكِ يَوۡمِ ٱلدِّينِ','انصاف کے دن کا حاکم','Master of the Day of Judgment','रोज़े जज़ा का मालिक है।');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (1,5,'Al-Faatiha','إِيَّاكَ نَعۡبُدُ وَإِيَّاكَ نَسۡتَعِينُ','(اے پروردگار) ہم تیری ہی عبادت کرتے ہیں اور تجھ ہی سے مدد مانگتے ہیں','You ˹alone˺ we worship and You ˹alone˺ we ask for help','हम तेरी ही इबादत करते हैं, और तुझ ही से मदद मांगते है।');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (1,6,'Al-Faatiha','ٱهۡدِنَا ٱلصِّرَٰطَ ٱلۡمُسۡتَقِيمَ','ہم کو سیدھے رستے چلا','Guide us along the Straight Path','हमें सीधा रास्ता दिखा।');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (1,7,'Al-Faatiha','صِرَٰطَ ٱلَّذِينَ أَنۡعَمۡتَ عَلَيۡهِمۡ غَيۡرِ ٱلۡمَغۡضُوبِ عَلَيۡهِمۡ وَلَا ٱلضَّآلِّينَ','ان لوگوں کے رستے جن پر تو اپنا فضل وکرم کرتا رہا نہ ان کے جن پر غصے ہوتا رہا اور نہ گمراہوں کے','the Path of those You have blessed—not those You are displeased with, or those who are astray','उन लोगों का रास्ता जिन पर तूने इनाम फ़रमाया, जो माअतूब नहीं हुए, जो भटके हुए नहीं है।');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,1,'Al-Baqara','الٓمٓ','الم','Alif-Lãm-Mĩm','अलीफ़ लाम मीम');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,2,'Al-Baqara','ذَٰلِكَ ٱلۡكِتَٰبُ لَا رَيۡبَۛ فِيهِۛ هُدࣰ ى لِّلۡمُتَّقِينَ','یہ کتاب (قرآن مجید) اس میں کچھ شک نہیں (کہ کلامِ خدا ہے۔ خدا سے) ڈرنے والوں کی رہنما ہے','This is the Book! There is no doubt about it—a guide for those mindful ˹of Allah˺','(ये) वह किताब है। जिस (के किताबे खुदा होने) में कुछ भी शक नहीं (ये) परहेज़गारों की रहनुमा है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,3,'Al-Baqara','ٱلَّذِينَ يُؤۡمِنُونَ بِٱلۡغَيۡبِ وَيُقِيمُونَ ٱلصَّلَوٰةَ وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ','جو غیب پر ایمان لاتے اور آداب کے ساتھ نماز پڑھتے اور جو کچھ ہم نے ان کو عطا فرمایا ہے اس میں سے خرچ کرتے ہیں','who believe in the unseen, establish prayer, and donate from what We have provided for them','जो ग़ैब पर ईमान लाते हैं और (पाबन्दी से) नमाज़ अदा करते हैं और जो कुछ हमने उनको दिया है उसमें से (राहे खुदा में) ख़र्च करते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,4,'Al-Baqara','وَٱلَّذِينَ يُؤۡمِنُونَ بِمَآ أُنزِلَ إِلَيۡكَ وَمَآ أُنزِلَ مِن قَبۡلِكَ وَبِٱلۡأٓخِرَةِ هُمۡ يُوقِنُونَ','اور جو کتاب (اے محمدﷺ) تم پر نازل ہوئی اور جو کتابیں تم سے پہلے (پیغمبروں پر) نازل ہوئیں سب پر ایمان لاتے اور آخرت کا یقین رکھتے ہیں','and who believe in what has been revealed to you ˹O Prophet˺ and what was revealed before you, and have sure faith in the Hereafter','और जो कुछ तुम पर (ऐ रसूल) और तुम से पहले नाज़िल किया गया है उस पर ईमान लाते हैं और वही आख़िरत का यक़ीन भी रखते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,5,'Al-Baqara','أُوْلَٰٓئِكَ عَلَىٰ هُدࣰ ى مِّن رَّبِّهِمۡۖ وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ','یہی لوگ اپنے پروردگار (کی طرف) سے ہدایت پر ہیں اور یہی نجات پانے والے ہیں','It is they who are ˹truly˺ guided by their Lord, and it is they who will be successful','यही लोग अपने परवरदिगार की हिदायत पर (आमिल) हैं और यही लोग अपनी दिली मुरादें पाएँगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,6,'Al-Baqara','إِنَّ ٱلَّذِينَ كَفَرُواْ سَوَآءٌ عَلَيۡهِمۡ ءَأَنذَرۡتَهُمۡ أَمۡ لَمۡ تُنذِرۡهُمۡ لَا يُؤۡمِنُونَ','جو لوگ کافر ہیں انہیں تم نصیحت کرو یا نہ کرو ان کے لیے برابر ہے۔ وہ ایمان نہیں لانے کے','As for those who persist in disbelief, it is the same whether you warn them or not—they will never believe','बेशक जिन लोगों ने कुफ़्र इख़तेयार किया उनके लिए बराबर है (ऐ रसूल) ख्वाह (चाहे) तुम उन्हें डराओ या न डराओ वह ईमान न लाएँगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,7,'Al-Baqara','خَتَمَ ٱللَّهُ عَلَىٰ قُلُوبِهِمۡ وَعَلَىٰ سَمۡعِهِمۡۖ وَعَلَىٰٓ أَبۡصَٰرِهِمۡ غِشَٰوَةࣱۖ وَلَهُمۡ عَذَابٌ عَظِيمࣱ‏','خدا نے ان کے دلوں اور کانوں پر مہر لگا رکھی ہے اور ان کی آنکھوں پر پردہ (پڑا ہوا) ہے اور ان کے لیے بڑا عذاب (تیار) ہے','Allah has sealed their hearts and their hearing, and their sight is covered. They will suffer a tremendous punishment','उनके दिलों पर और उनके कानों पर (नज़र करके) खुदा ने तसदीक़ कर दी है (कि ये ईमान न लाएँगे) और उनकी ऑंखों पर परदा (पड़ा हुआ) है और उन्हीं के लिए (बहुत) बड़ा अज़ाब है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,8,'Al-Baqara','وَمِنَ ٱلنَّاسِ مَن يَقُولُ ءَامَنَّا بِٱللَّهِ وَبِٱلۡيَوۡمِ ٱلۡأٓخِرِ وَمَا هُم بِمُؤۡمِنِينَ','اور بعض لوگ ایسے ہیں جو کہتے ہیں کہ ہم خدا پر اور روزِ آخرت پر ایمان رکھتے ہیں حالانکہ وہ ایمان نہیں رکھتے','And there are some who say, “We believe in Allah and the Last Day,” yet they are not ˹true˺ believers','और बाज़ लोग ऐसे भी हैं जो (ज़बान से तो) कहते हैं कि हम खुदा पर और क़यामत पर ईमान लाए हालाँकि वह दिल से ईमान नहीं लाए');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,9,'Al-Baqara','يُخَٰدِعُونَ ٱللَّهَ وَٱلَّذِينَ ءَامَنُواْ وَمَا يَخۡدَعُونَ إِلَّآ أَنفُسَهُمۡ وَمَا يَشۡعُرُونَ','یہ (اپنے پندار میں) خدا کو اور مومنوں کو چکما دیتے ہیں مگر (حقیقت میں) اپنے سوا کسی کو چکما نہیں دیتے اور اس سے بے خبر ہیں','They seek to deceive Allah and the believers, yet they only deceive themselves, but they fail to perceive it','खुदा को और उन लोगों को जो ईमान लाए धोखा देते हैं हालाँकि वह अपने आपको धोखा देते हैं और कुछ शऊर नहीं रखते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,10,'Al-Baqara','فِي قُلُوبِهِم مَّرَضࣱ فَزَادَهُمُ ٱللَّهُ مَرَضࣰ اۖ وَلَهُمۡ عَذَابٌ أَلِيمُۢ بِمَا كَانُواْ يَكۡذِبُونَ','ان کے دلوں میں (کفر کا) مرض تھا۔ خدا نے ان کا مرض اور زیادہ کر دیا اور ان کے جھوٹ بولنے کے سبب ان کو دکھ دینے والا عذاب ہوگا','There is sickness in their hearts, and Allah ˹only˺ lets their sickness increase. They will suffer a painful punishment for their lies','उनके दिलों में मर्ज़ था ही अब खुदा ने उनके मर्ज़ को और बढ़ा दिया और चूँकि वह लोग झूठ बोला करते थे इसलिए उन पर तकलीफ देह अज़ाब है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,11,'Al-Baqara','وَإِذَا قِيلَ لَهُمۡ لَا تُفۡسِدُواْ فِي ٱلۡأَرۡضِ قَالُوٓاْ إِنَّمَا نَحۡنُ مُصۡلِحُونَ','اور جب ان سے کہا جاتا ہے کہ زمین میں فساد نہ ڈالو تو کہتے ہیں، ہم تو اصلاح کرنے والے ہیں','When they are told, “Do not spread corruption in the land,” they reply, “We are only peace-makers!”','और जब उनसे कहा जाता है कि मुल्क में फसाद न करते फिरो (तो) कहते हैं कि हम तो सिर्फ इसलाह करते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,12,'Al-Baqara','أَلَآ إِنَّهُمۡ هُمُ ٱلۡمُفۡسِدُونَ وَلَٰكِن لَّا يَشۡعُرُونَ','دیکھو یہ بلاشبہ مفسد ہیں، لیکن خبر نہیں رکھتے','Indeed, it is they who are the corruptors, but they fail to perceive it','ख़बरदार हो जाओ बेशक यही लोग फसादी हैं लेकिन समझते नहीं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,13,'Al-Baqara','وَإِذَا قِيلَ لَهُمۡ ءَامِنُواْ كَمَآ ءَامَنَ ٱلنَّاسُ قَالُوٓاْ أَنُؤۡمِنُ كَمَآ ءَامَنَ ٱلسُّفَهَآءُۗ أَلَآ إِنَّهُمۡ هُمُ ٱلسُّفَهَآءُ وَلَٰكِن لَّا يَعۡلَمُونَ','اور جب ان سے کہا جاتا ہے کہ جس طرح اور لوگ ایمان لے آئے، تم بھی ایمان لے آؤ تو کہتے ہیں، بھلا جس طرح بےوقوف ایمان لے آئے ہیں اسی طرح ہم بھی ایمان لے آئیں؟ سن لو کہ یہی بےوقوف ہیں لیکن نہیں جانتے','And when they are told, “Believe as others believe,” they reply, “Will we believe as the fools believe?” Indeed, it is they who are fools, but they do not know','और जब उनसे कहा जाता है कि जिस तरह और लोग ईमान लाए हैं तुम भी ईमान लाओ तो कहते हैं क्या हम भी उसी तरह ईमान लाएँ जिस तरह और बेवकूफ़ लोग ईमान लाएँ, ख़बरदार हो जाओ लोग बेवक़ूफ़ हैं लेकिन नहीं जानते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,14,'Al-Baqara','وَإِذَا لَقُواْ ٱلَّذِينَ ءَامَنُواْ قَالُوٓاْ ءَامَنَّا وَإِذَا خَلَوۡاْ إِلَىٰ شَيَٰطِينِهِمۡ قَالُوٓاْ إِنَّا مَعَكُمۡ إِنَّمَا نَحۡنُ مُسۡتَهۡزِءُونَ','اور یہ لوگ جب مومنوں سے ملتے ہیں تو کہتے ہیں کہ ہم ایمان لے آئے ہیں، اور جب اپنے شیطانوں میں جاتے ہیں تو (ان سے) کہتے ہیں کہ ہم تمھارے ساتھ ہیں اور (پیروانِ محمدﷺ سے) تو ہم ہنسی کیا کرتے ہیں','When they meet the believers they say, “We believe.” But when alone with their evil associates they say, “We are definitely with you; we were only mocking.”','और जब उन लोगों से मिलते हैं जो ईमान ला चुके तो कहते हैं हम तो ईमान ला चुके और जब अपने शैतानों के साथ तनहा रह जाते हैं तो कहते हैं हम तुम्हारे साथ हैं हम तो (मुसलमानों को) बनाते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,15,'Al-Baqara','ٱللَّهُ يَسۡتَهۡزِئُ بِهِمۡ وَيَمُدُّهُمۡ فِي طُغۡيَٰنِهِمۡ يَعۡمَهُونَ','ان (منافقوں) سے خدا ہنسی کرتا ہے اور انہیں مہلت دیئے جاتا ہے کہ شرارت وسرکشی میں پڑے بہک رہے ہیں','Allah will throw their mockery back at them, leaving them to continue wandering blindly in their defiance','(वह क्या बनाएँगे) खुदा उनको बनाता है और उनको ढील देता है कि वह अपनी सरकशी में ग़लत पेचाँ (उलझे) रहें');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,16,'Al-Baqara','أُوْلَٰٓئِكَ ٱلَّذِينَ ٱشۡتَرَوُاْ ٱلضَّلَٰلَةَ بِٱلۡهُدَىٰ فَمَا رَبِحَت تِّجَٰرَتُهُمۡ وَمَا كَانُواْ مُهۡتَدِينَ','یہ وہ لوگ ہیں جنہوں نے ہدایت چھوڑ کر گمراہی خریدی، تو نہ تو ان کی تجارت ہی نے کچھ نفع دیا اور نہ وہ ہدایت یاب ہی ہوئے','They are the ones who trade guidance for misguidance. But this trade is profitless, and they are not ˹rightly˺ guided','यही वह लोग हैं जिन्होंने हिदायत के बदले गुमराही ख़रीद ली, फिर न उनकी तिजारत ही ने कुछ नफ़ा दिया और न उन लोगों ने हिदायत ही पाई');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,17,'Al-Baqara','مَثَلُهُمۡ كَمَثَلِ ٱلَّذِي ٱسۡتَوۡقَدَ نَارࣰ ا فَلَمَّآ أَضَآءَتۡ مَا حَوۡلَهُۥ ذَهَبَ ٱللَّهُ بِنُورِهِمۡ وَتَرَكَهُمۡ فِي ظُلُمَٰتࣲ لَّا يُبۡصِرُونَ','ان کی مثال اس شخص کی سی ہے کہ جس نے (شبِ تاریک میں) آگ جلائی۔ جب آگ نے اس کے اردگرد کی چیزیں روشن کیں تو خدا نے ان کی روشنی زائل کر دی اور ان کو اندھیروں میں چھوڑ دیا کہ کچھ نہیں دیکھتے','Their example is that of someone who kindles a fire, but when it lights up all around them, Allah takes away their light, leaving them in complete darkness—unable to see','उन लोगों की मिसाल (तो) उस शख्स की सी है जिसने (रात के वक्त मजमे में) भड़कती हुईआग रौशन की फिर जब आग (के शोले) ने उसके गिर्दों पेश (चारों ओर) खूब उजाला कर दिया तो खुदा ने उनकी रौशनी ले ली और उनको घटाटोप अंधेरे में छोड़ दिया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,18,'Al-Baqara','صُمُّۢ بُكۡمٌ عُمۡيࣱ فَهُمۡ لَا يَرۡجِعُونَ','(یہ) بہرے ہیں، گونگے ہیں، اندھے ہیں کہ (کسی طرح سیدھے رستے کی طرف) لوٹ ہی نہیں سکتے','They are ˹wilfully˺ deaf, dumb, and blind, so they will never return ˹to the Right Path˺','कि अब उन्हें कुछ सुझाई नहीं देता ये लोग बहरे गूँगे अन्धे हैं कि फिर अपनी गुमराही से बाज़ नहीं आ सकते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,19,'Al-Baqara','أَوۡ كَصَيِّبࣲ مِّنَ ٱلسَّمَآءِ فِيهِ ظُلُمَٰتࣱ وَرَعۡدࣱ وَبَرۡقࣱ يَجۡعَلُونَ أَصَٰبِعَهُمۡ فِيٓ ءَاذَانِهِم مِّنَ ٱلصَّوَٰعِقِ حَذَرَ ٱلۡمَوۡتِۚ وَٱللَّهُ مُحِيطُۢ بِٱلۡكَٰفِرِينَ','یا ان کی مثال مینہ کی سی ہے کہ آسمان سے (برس رہا ہو اور) اس میں اندھیرے پر اندھیرا (چھا رہا) ہو اور (بادل) گرج (رہا) ہو اور بجلی (کوند رہی) ہو تو یہ کڑک سے (ڈر کر) موت کے خوف سے کانوں میں انگلیاں دے لیں اور الله کافروں کو (ہر طرف سے) گھیرے ہوئے ہے','Or ˹those caught in˺ a rainstorm from the sky with darkness, thunder, and lightning. They press their fingers into their ears at the sound of every thunder-clap for fear of death. And Allah encompasses the disbelievers ˹by His might˺','या उनकी मिसाल ऐसी है जैसे आसमानी बारिश जिसमें तारिकियाँ ग़र्ज़ बिजली हो मौत के खौफ से कड़क के मारे अपने कानों में ऊँगलियाँ दे लेते हैं हालाँकि खुदा काफ़िरों को (इस तरह) घेरे हुए है (कि उसक हिल नहीं सकते)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,20,'Al-Baqara','يَكَادُ ٱلۡبَرۡقُ يَخۡطَفُ أَبۡصَٰرَهُمۡۖ كُلَّمَآ أَضَآءَ لَهُم مَّشَوۡاْ فِيهِ وَإِذَآ أَظۡلَمَ عَلَيۡهِمۡ قَامُواْۚ وَلَوۡ شَآءَ ٱللَّهُ لَذَهَبَ بِسَمۡعِهِمۡ وَأَبۡصَٰرِهِمۡۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءࣲ قَدِيرࣱ‏','قریب ہے کہ بجلی (کی چمک) ان کی آنکھوں (کی بصارت) کو اچک لے جائے۔ جب بجلی (چمکتی اور) ان پر روشنی ڈالی ہے تو اس میں چل پڑتے ہیں اور جب اندھیرا ہو جاتا ہے تو کھڑے کے کھڑے رہ جاتے ہیں اور اگر الله چاہتا تو ان کے کانوں (کی شنوائی) اور آنکھوں (کی بینائی دونوں) کو زائل کر دیتا ہے۔ بے شک الله ہر چیز پر قادر ہے','It is as if the lightning were about to snatch away their sight. Whenever lightning strikes, they walk in its light, but when darkness covers them, they stand still. Had Allah willed, He could have taken away their hearing and sight. Surely Allah is Most Capable of everything','क़रीब है कि बिजली उनकी ऑंखों को चौन्धिया दे जब उनके आगे बिजली चमकी तो उस रौशनी में चल खड़े हुए और जब उन पर अंधेरा छा गया तो (ठिठके के) खड़े हो गए और खुदा चाहता तो यूँ भी उनके देखने और सुनने की कूवतें छीन लेता बेशक खुदा हर चीज़ पर क़ादिर है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,21,'Al-Baqara','يَٰٓأَيُّهَا ٱلنَّاسُ ٱعۡبُدُواْ رَبَّكُمُ ٱلَّذِي خَلَقَكُمۡ وَٱلَّذِينَ مِن قَبۡلِكُمۡ لَعَلَّكُمۡ تَتَّقُونَ','لوگو! اپنے پروردگار کی عبات کرو جس نے تم کو اور تم سے پہلے لوگوں کو پیدا کیا تاکہ تم (اس کے عذاب سے) بچو','O humanity! Worship your Lord, Who created you and those before you, so that you may become mindful ˹of Him˺','ऐ लोगों अपने परवरदिगार की इबादत करो जिसने तुमको और उन लोगों को जो तुम से पहले थे पैदा किया है अजब नहीं तुम परहेज़गार बन जाओ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,22,'Al-Baqara','ٱلَّذِي جَعَلَ لَكُمُ ٱلۡأَرۡضَ فِرَٰشࣰ ا وَٱلسَّمَآءَ بِنَآءࣰ وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءࣰ فَأَخۡرَجَ بِهِۦ مِنَ ٱلثَّمَرَٰتِ رِزۡقࣰ ا لَّكُمۡۖ فَلَا تَجۡعَلُواْ لِلَّهِ أَندَادࣰ ا وَأَنتُمۡ تَعۡلَمُونَ','جس نے تمھارے لیے زمین کو بچھونا اور آسمان کو چھت بنایا اور آسمان سے مینہ برسا کر تمہارے کھانے کے لیے انواع و اقسام کے میوے پیدا کئے۔ پس کسی کو خدا کا ہمسر نہ بناؤ۔ اور تم جانتے تو ہو','˹He is the One˺ Who has made the earth a place of settlement for you and the sky a canopy; and sends down rain from the sky, causing fruits to grow as a provision for you. So do not knowingly set up equals to Allah ˹in worship˺','जिसने तुम्हारे लिए ज़मीन का बिछौना और आसमान को छत बनाया और आसमान से पानी बरसाया फिर उसी ने तुम्हारे खाने के लिए बाज़ फल पैदा किए पस किसी को खुदा का हमसर न बनाओ हालाँकि तुम खूब जानते हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,23,'Al-Baqara','وَإِن كُنتُمۡ فِي رَيۡبࣲ مِّمَّا نَزَّلۡنَا عَلَىٰ عَبۡدِنَا فَأۡتُواْ بِسُورَةࣲ مِّن مِّثۡلِهِۦ وَٱدۡعُواْ شُهَدَآءَكُم مِّن دُونِ ٱللَّهِ إِن كُنتُمۡ صَٰدِقِينَ','اور اگر تم کو اس (کتاب) میں، جو ہم نے اپنے بندے (محمدﷺ عربی) پر نازل فرمائی ہے کچھ شک ہو تو اسی طرح کی ایک سورت تم بھی بنا لاؤ اور خدا کے سوا جو تمہارے مددگار ہوں ان کو بھی بلالو اگر تم سچے ہو','And if you are in doubt about what We have revealed to Our servant, then produce a sûrah like it and call your helpers other than Allah, if what you say is true','और अगर तुम लोग इस कलाम से जो हमने अपने बन्दे (मोहम्मद) पर नाज़िल किया है शक में पड़े हो पस अगर तुम सच्चे हो तो तुम (भी) एक सूरा बना लाओ और खुदा के सिवा जो भी तुम्हारे मददगार हों उनको भी बुला लो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,24,'Al-Baqara','فَإِن لَّمۡ تَفۡعَلُواْ وَلَن تَفۡعَلُواْ فَٱتَّقُواْ ٱلنَّارَ ٱلَّتِي وَقُودُهَا ٱلنَّاسُ وَٱلۡحِجَارَةُۖ أُعِدَّتۡ لِلۡكَٰفِرِينَ','لیکن اگر (ایسا) نہ کر سکو اور ہرگز نہیں کر سکو گے تو اس آگ سے ڈرو جس کا ایندھن آدمی اور پتھر ہوں گے (اور جو) کافروں کے لیے تیار کی گئی ہے','But if you are unable to do so—and you will never be able to do so—then fear the Fire fuelled with people and stones, which is prepared for the disbelievers','पस अगर तुम ये नहीं कर सकते हो और हरगिज़ नहीं कर सकोगे तो उस आग से डरो सिके ईधन आदमी और पत्थर होंगे और काफ़िरों के लिए तैयार की गई है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,25,'Al-Baqara','وَبَشِّرِ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ أَنَّ لَهُمۡ جَنَّٰتࣲ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۖ كُلَّمَا رُزِقُواْ مِنۡهَا مِن ثَمَرَةࣲ رِّزۡقࣰ ا قَالُواْ هَٰذَا ٱلَّذِي رُزِقۡنَا مِن قَبۡلُۖ وَأُتُواْ بِهِۦ مُتَشَٰبِهࣰ اۖ وَلَهُمۡ فِيهَآ أَزۡوَٰجࣱ مُّطَهَّرَةࣱۖ وَهُمۡ فِيهَا خَٰلِدُونَ','اور جو لوگ ایمان لائے اور نیک عمل کرتے رہے، ان کو خوشخبری سنا دو کہ ان کے لیے (نعمت کے) باغ ہیں، جن کے نیچے نہریں بہہ رہی ہیں۔ جب انہیں ان میں سے کسی قسم کا میوہ کھانے کو دیا جائے گا تو کہیں گے، یہ تو وہی ہے جو ہم کو پہلے دیا گیا تھا۔ اور ان کو ایک دوسرے کے ہم شکل میوے دیئے جائیں گے اور وہاں ان کے لیے پاک بیویاں ہوں گی اور وہ بہشتوں میں ہمیشہ رہیں گے','Give good news ˹O Prophet˺ to those who believe and do good that they will have Gardens under which rivers flow. Whenever provided with fruit, they will say, “This is what we were given before,” for they will be served fruit that looks similar ˹but tastes different˺. They will have pure spouses, and they will be there forever','और जो लोग ईमान लाए और उन्होंने नेक काम किए उनको (ऐ पैग़म्बर) खुशख़बरी दे दो कि उनके लिए (बेहिश्त के) वह बाग़ात हैं जिनके नीचे नहरे जारी हैं जब उन्हें इन बाग़ात का कोई मेवा खाने को मिलेगा तो कहेंगे ये तो वही (मेवा है जो पहले भी हमें खाने को मिल चुका है) (क्योंकि) उन्हें मिलती जुलती सूरत व रंग के (मेवे) मिला करेंगे और बेहिश्त में उनके लिए साफ सुथरी बीवियाँ होगी और ये लोग उस बाग़ में हमेशा रहेंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,26,'Al-Baqara','۞إِنَّ ٱللَّهَ لَا يَسۡتَحۡيِۦٓ أَن يَضۡرِبَ مَثَلࣰ ا مَّا بَعُوضَةࣰ فَمَا فَوۡقَهَاۚ فَأَمَّا ٱلَّذِينَ ءَامَنُواْ فَيَعۡلَمُونَ أَنَّهُ ٱلۡحَقُّ مِن رَّبِّهِمۡۖ وَأَمَّا ٱلَّذِينَ كَفَرُواْ فَيَقُولُونَ مَاذَآ أَرَادَ ٱللَّهُ بِهَٰذَا مَثَلࣰ اۘ يُضِلُّ بِهِۦ كَثِيرࣰ ا وَيَهۡدِي بِهِۦ كَثِيرࣰ اۚ وَمَا يُضِلُّ بِهِۦٓ إِلَّا ٱلۡفَٰسِقِينَ','الله اس بات سے عار نہیں کرتا کہ مچھر یا اس سے بڑھ کر کسی چیز (مثلاً مکھی مکڑی وغیرہ) کی مثال بیان فرمائے۔ جو مومن ہیں، وہ یقین کرتے ہیں وہ ان کے پروردگار کی طرف سے سچ ہے اور جو کافر ہیں وہ کہتے ہیں کہ اس مثال سے خدا کی مراد ہی کیا ہے۔ اس سے (خدا) بہتوں کو گمراہ کرتا ہے اور بہتوں کو ہدایت بخشتا ہے اور گمراہ بھی کرتا تو نافرمانوں ہی کو','Surely Allah does not shy away from using the parable of a mosquito or what is even smaller. As for the believers, they know that it is the truth from their Lord. And as for the disbelievers, they argue, “What does Allah mean by such a parable?” Through this ˹test˺, He leaves many to stray, and guides many. And He leaves none to stray except the rebellious—','बेशक खुदा मच्छर या उससे भी बढ़कर (हक़ीर चीज़) की कोई मिसाल बयान करने में नहीं झेंपता पस जो लोग ईमान ला चुके हैं वह तो ये यक़ीन जानते हैं कि ये (मिसाल) बिल्कुल ठीक है और ये परवरदिगार की तरफ़ से है (अब रहे) वह लोग जो काफ़िर है पस वह बोल उठते हैं कि खुदा का उस मिसाल से क्या मतलब है, ऐसी मिसाल से ख़ुदा बहुतेरों की हिदायत करता है मगर गुमराही में छोड़ता भी है तो ऐसे बदकारों को');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,27,'Al-Baqara','ٱلَّذِينَ يَنقُضُونَ عَهۡدَ ٱللَّهِ مِنۢ بَعۡدِ مِيثَٰقِهِۦ وَيَقۡطَعُونَ مَآ أَمَرَ ٱللَّهُ بِهِۦٓ أَن يُوصَلَ وَيُفۡسِدُونَ فِي ٱلۡأَرۡضِۚ أُوْلَٰٓئِكَ هُمُ ٱلۡخَٰسِرُونَ','جو خدا کے اقرار کو مضبوط کرنے کے بعد توڑ دیتے ہیں اور جس چیز (یعنی رشتہٴ قرابت) کے جوڑے رکھنے کا الله نے حکم دیا ہے اس کو قطع کئے ڈالتے ہیں اور زمین میں خرابی کرتے ہیں یہی لوگ نقصان اٹھانے والے ہیں','those who violate Allah’s covenant after it has been affirmed, break whatever ˹ties˺ Allah has ordered to be maintained, and spread corruption in the land. It is they who are the ˹true˺ losers','जो लोग खुदा के एहदो पैमान को मज़बूत हो जाने के बाद तोड़ डालते हैं और जिन (ताल्लुक़ात) का खुदा ने हुक्म दिया है उनको क़ताआ कर देते हैं और मुल्क में फसाद करते फिरते हैं, यही लोग घाटा उठाने वाले हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,28,'Al-Baqara','كَيۡفَ تَكۡفُرُونَ بِٱللَّهِ وَكُنتُمۡ أَمۡوَٰتࣰ ا فَأَحۡيَٰكُمۡۖ ثُمَّ يُمِيتُكُمۡ ثُمَّ يُحۡيِيكُمۡ ثُمَّ إِلَيۡهِ تُرۡجَعُونَ','(کافرو!) تم خدا سے کیوں کر منکر ہو سکتے ہو جس حال میں کہ تم بےجان تھے تو اس نے تم کو جان بخشی پھر وہی تم کو مارتا ہے پھر وہی تم کو زندہ کرے گا پھر تم اسی کی طرف لوٹ کر جاؤ گے','How can you deny Allah? You were lifeless and He gave you life, then He will cause you to die and again bring you to life, and then to Him you will ˹all˺ be returned','(हाँए) क्यों कर तुम खुदा का इन्कार कर सकते हो हालाँकि तुम (माओं के पेट में) बेजान थे तो उसी ने तुमको ज़िन्दा किया फिर वही तुमको मार डालेगा, फिर वही तुमको (दोबारा क़यामत में) ज़िन्दा करेगा फिर उसी की तरफ लौटाए जाओगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,29,'Al-Baqara','هُوَ ٱلَّذِي خَلَقَ لَكُم مَّا فِي ٱلۡأَرۡضِ جَمِيعࣰ ا ثُمَّ ٱسۡتَوَىٰٓ إِلَى ٱلسَّمَآءِ فَسَوَّىٰهُنَّ سَبۡعَ سَمَٰوَٰتࣲۚ وَهُوَ بِكُلِّ شَيۡءٍ عَلِيمࣱ‏','وہی تو ہے جس نے سب چیزیں جو زمین میں ہیں تمہارے لیے پیدا کیں پھر آسمان کی طرف متوجہ ہوا تو ان کو ٹھیک سات آسمان بنا دیا اور وہ ہر چیز سے خبردار ہے','He is the One Who created everything in the earth for you. Then He turned towards the heaven, forming it into seven heavens. And He has ˹perfect˺ knowledge of all things','वही तो वह (खुदा) है जिसने तुम्हारे (नफ़े) के ज़मीन की कुल चीज़ों को पैदा किया फिर आसमान (के बनाने) की तरफ़ मुतावज्जेह हुआ तो सात आसमान हमवार (व मुसतहकम) बना दिए और वह (खुदा) हर चीज़ से (खूब) वाक़िफ है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,30,'Al-Baqara','وَإِذۡ قَالَ رَبُّكَ لِلۡمَلَٰٓئِكَةِ إِنِّي جَاعِلࣱ فِي ٱلۡأَرۡضِ خَلِيفَةࣰۖ قَالُوٓاْ أَتَجۡعَلُ فِيهَا مَن يُفۡسِدُ فِيهَا وَيَسۡفِكُ ٱلدِّمَآءَ وَنَحۡنُ نُسَبِّحُ بِحَمۡدِكَ وَنُقَدِّسُ لَكَۖ قَالَ إِنِّيٓ أَعۡلَمُ مَا لَا تَعۡلَمُونَ','اور (وہ وقت یاد کرنے کے قابل ہے) جب تمہارے پروردگار نے فرشتوں سے فرمایا کہ میں زمین میں (اپنا) نائب بنانے والا ہوں۔ انہوں نے کہا۔ کیا تُو اس میں ایسے شخص کو نائب بنانا چاہتا ہے جو خرابیاں کرے اور کشت وخون کرتا پھرے اور ہم تیری تعریف کے ساتھ تسبیح وتقدیس کرتے رہتے ہیں۔ (خدا نے) فرمایا میں وہ باتیں جانتا ہوں جو تم نہیں جانتے','˹Remember˺ when your Lord said to the angels, “I am going to place a successive ˹human˺ authority on earth.” They asked ˹Allah˺, “Will You place in it someone who will spread corruption there and shed blood while we glorify Your praises and proclaim Your holiness?” Allah responded, “I know what you do not know.”','और (ऐ रसूल) उस वक्त क़ो याद करो जब तुम्हारे परवरदिगार ने फ़रिश्तों से कहा कि मैं (अपना) एक नाएब ज़मीन में बनानेवाला हूँ (फरिश्ते ताज्जुब से) कहने लगे क्या तू ज़मीन ऐसे शख्स को पैदा करेगा जो ज़मीन में फ़साद और खूँरेज़ियाँ करता फिरे हालाँकि (अगर) ख़लीफा बनाना है (तो हमारा ज्यादा हक़ है) क्योंकि हम तेरी तारीफ व तसबीह करते हैं और तेरी पाकीज़गी साबित करते हैं तब खुदा ने फरमाया इसमें तो शक ही नहीं कि जो मैं जानता हूँ तुम नहीं जानते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,31,'Al-Baqara','وَعَلَّمَ ءَادَمَ ٱلۡأَسۡمَآءَ كُلَّهَا ثُمَّ عَرَضَهُمۡ عَلَى ٱلۡمَلَٰٓئِكَةِ فَقَالَ أَنۢبِـُٔونِي بِأَسۡمَآءِ هَٰٓؤُلَآءِ إِن كُنتُمۡ صَٰدِقِينَ','اور اس نے آدم کو سب (چیزوں کے) نام سکھائے پھر ان کو فرشتوں کے سامنے کیا اور فرمایا کہ اگر تم سچے ہو تو مجھے ان کے نام بتاؤ','He taught Adam the names of all things, then He presented them to the angels and said, “Tell Me the names of these, if what you say is true?”','और (आदम की हक़ीक़म ज़ाहिर करने की ग़रज़ से) आदम को सब चीज़ों के नाम सिखा दिए फिर उनको फरिश्तों के सामने पेश किया और फ़रमाया कि अगर तुम अपने दावे में कि हम मुस्तहके ख़िलाफ़त हैं। सच्चे हो तो मुझे इन चीज़ों के नाम बताओ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,32,'Al-Baqara','قَالُواْ سُبۡحَٰنَكَ لَا عِلۡمَ لَنَآ إِلَّا مَا عَلَّمۡتَنَآۖ إِنَّكَ أَنتَ ٱلۡعَلِيمُ ٱلۡحَكِيمُ','انہوں نے کہا، تو پاک ہے۔ جتنا علم تو نے ہمیں بخشا ہے، اس کے سوا ہمیں کچھ معلوم نہیں۔ بے شک تو دانا (اور) حکمت والا ہے','They replied, “Glory be to You! We have no knowledge except what You have taught us. You are truly the All-Knowing, All-Wise.”','तब फ़रिश्तों ने (आजिज़ी से) अर्ज़ की तू (हर ऐब से) पाक व पाकीज़ा है हम तो जो कुछ तूने बताया है उसके सिवा कुछ नहीं जानते तू बड़ा जानने वाला, मसलहतों का पहचानने वाला है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,33,'Al-Baqara','قَالَ يَٰٓـَٔادَمُ أَنۢبِئۡهُم بِأَسۡمَآئِهِمۡۖ فَلَمَّآ أَنۢبَأَهُم بِأَسۡمَآئِهِمۡ قَالَ أَلَمۡ أَقُل لَّكُمۡ إِنِّيٓ أَعۡلَمُ غَيۡبَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَأَعۡلَمُ مَا تُبۡدُونَ وَمَا كُنتُمۡ تَكۡتُمُونَ','(تب) خدا نے (آدم کو) حکم دیا کہ آدم! تم ان کو ان (چیزوں) کے نام بتاؤ۔ جب انہوں نے ان کو ان کے نام بتائے تو (فرشتوں سے) فرمایا کیوں میں نے تم سے نہیں کہا تھا کہ میں آسمانوں اور زمین کی (سب) پوشیدہ باتیں جاتنا ہوں اور جو تم ظاہر کرتے ہو اور جو پوشیدہ کرتے ہو (سب) مجھ کو معلوم ہے','Allah said, “O Adam! Inform them of their names.” Then when Adam did, Allah said, “Did I not tell you that I know the secrets of the heavens and the earth, and I know what you reveal and what you conceal?”','(उस वक्त ख़ुदा ने आदम को) हुक्म दिया कि ऐ आदम तुम इन फ़रिश्तों को उन सब चीज़ों के नाम बता दो बस जब आदम ने फ़रिश्तों को उन चीज़ों के नाम बता दिए तो खुदा ने फरिश्तों की तरफ ख़िताब करके फरमाया क्यों, मैं तुमसे न कहता था कि मैं आसमानों और ज़मीनों के छिपे हुए राज़ को जानता हूँ, और जो कुछ तुम अब ज़ाहिर करते हो और जो कुछ तुम छिपाते थे (वह सब) जानता हूँ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,34,'Al-Baqara','وَإِذۡ قُلۡنَا لِلۡمَلَٰٓئِكَةِ ٱسۡجُدُواْ لِأٓدَمَ فَسَجَدُوٓاْ إِلَّآ إِبۡلِيسَ أَبَىٰ وَٱسۡتَكۡبَرَ وَكَانَ مِنَ ٱلۡكَٰفِرِينَ','اور جب ہم نے فرشتوں کو حکم دیا کہ آدم کے آگے سجدہ کرو تو وہ سجدے میں گر پڑے مگر شیطان نے انکار کیا اور غرور میں آکر کافر بن گیا','And ˹remember˺ when We said to the angels, “Prostrate before Adam,” so they all did—but not Iblîs, who refused and acted arrogantly, becoming unfaithful','और (उस वक्त क़ो याद करो) जब हमने फ़रिश्तों से कहा कि आदम को सजदा करो तो सब के सब झुक गए मगर शैतान ने इन्कार किया और ग़ुरूर में आ गया और काफ़िर हो गया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,35,'Al-Baqara','وَقُلۡنَا يَٰٓـَٔادَمُ ٱسۡكُنۡ أَنتَ وَزَوۡجُكَ ٱلۡجَنَّةَ وَكُلَا مِنۡهَا رَغَدًا حَيۡثُ شِئۡتُمَا وَلَا تَقۡرَبَا هَٰذِهِ ٱلشَّجَرَةَ فَتَكُونَا مِنَ ٱلظَّٰلِمِينَ','اور ہم نے کہا کہ اے آدم تم اور تمہاری بیوی بہشت میں رہو اور جہاں سے چاہو بے روک ٹوک کھاؤ (پیو) لیکن اس درخت کے پاس نہ جانا نہیں تو ظالموں میں (داخل) ہو جاؤ گے','We cautioned, “O Adam! Live with your wife in Paradise and eat as freely as you please, but do not approach this tree, or else you will be wrongdoers.”','और हमने आदम से कहा ऐ आदम तुम अपनी बीवी समैत बेहिश्त में रहा सहा करो और जहाँ से तुम्हारा जी चाहे उसमें से ब फराग़त खाओ (पियो) मगर उस दरख्त के पास भी न जाना (वरना) फिर तुम अपना आप नुक़सान करोगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,36,'Al-Baqara','فَأَزَلَّهُمَا ٱلشَّيۡطَٰنُ عَنۡهَا فَأَخۡرَجَهُمَا مِمَّا كَانَا فِيهِۖ وَقُلۡنَا ٱهۡبِطُواْ بَعۡضُكُمۡ لِبَعۡضٍ عَدُوࣱّۖ وَلَكُمۡ فِي ٱلۡأَرۡضِ مُسۡتَقَرࣱّ وَمَتَٰعٌ إِلَىٰ حِينࣲ‏','پھر شیطان نے دونوں کو وہاں سے پھسلا دیا اور جس (عیش ونشاط) میں تھے، اس سے ان کو نکلوا دیا۔ تب ہم نے حکم دیا کہ (بہشت بریں سے) چلے جاؤ۔ تم ایک دوسرے کے دشمن ہو، اور تمہارے لیے زمین میں ایک وقت تک ٹھکانا اور معاش (مقرر کر دیا گیا) ہے','But Satan deceived them—leading to their fall from the ˹blissful˺ state they were in, and We said, “Descend from the heavens ˹to the earth˺ as enemies to each other. You will find in the earth a residence and provision for your appointed stay.”','तब शैतान ने आदम व हौव्वा को (धोखा देकर) वहाँ से डगमगाया और आख़िर कार उनको जिस (ऐश व राहत) में थे उनसे निकाल फेंका और हमने कहा (ऐ आदम व हौव्वा) तुम (ज़मीन पर) उतर पड़ो तुममें से एक का एक दुशमन होगा और ज़मीन में तुम्हारे लिए एक ख़ास वक्त (क़यामत) तक ठहराव और ठिकाना है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,37,'Al-Baqara','فَتَلَقَّىٰٓ ءَادَمُ مِن رَّبِّهِۦ كَلِمَٰتࣲ فَتَابَ عَلَيۡهِۚ إِنَّهُۥ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ','پھر آدم نے اپنے پروردگار سے کچھ کلمات سیکھے (اور معافی مانگی) تو اس نے ان کا قصور معاف کر دیا بے شک وہ معاف کرنے والا (اور) صاحبِ رحم ہے','Then Adam was inspired with words ˹of prayer˺ by his Lord, so He accepted his repentance. Surely He is the Accepter of Repentance, Most Merciful','फिर आदम ने अपने परवरदिगार से (माज़रत के चन्द अल्फाज़) सीखे पस खुदा ने उन अल्फाज़ की बरकत से आदम की तौबा कुबूल कर ली बेशक वह बड़ा माफ़ करने वाला मेहरबान है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,38,'Al-Baqara','قُلۡنَا ٱهۡبِطُواْ مِنۡهَا جَمِيعࣰ اۖ فَإِمَّا يَأۡتِيَنَّكُم مِّنِّي هُدࣰ ى فَمَن تَبِعَ هُدَايَ فَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ','ہم نے فرمایا کہ تم سب یہاں سے اتر جاؤ جب تمہارے پاس میری طرف سے ہدایت پہنچے تو (اس کی پیروی کرنا کہ) جنہوں نے میری ہدایت کی پیروی کی ان کو نہ کچھ خوف ہوگا اور نہ وہ غمناک ہوں گے','We said, “Descend all of you! Then when guidance comes to you from Me, whoever follows it, there will be no fear for them, nor will they grieve','(और जब आदम को) ये हुक्म दिया था कि यहाँ से उतर पड़ो (तो भी कह दिया था कि) अगर तुम्हारे पास मेरी तरफ़ से हिदायत आए तो (उसकी पैरवी करना क्योंकि) जो लोग मेरी हिदायत पर चलेंगे उन पर (क़यामत) में न कोई ख़ौफ होगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,39,'Al-Baqara','وَٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَآ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ','اور جنہوں نے (اس کو) قبول نہ کیا اور ہماری آیتوں کو جھٹلایا، وہ دوزخ میں جانے والے ہیں (اور) وہ ہمیشہ اس میں رہیں گے','But those who disbelieve and deny Our signs will be the residents of the Fire. They will be there forever.”','और न वह रंजीदा होगे और (ये भी याद रखो) जिन लोगों ने कुफ्र इख़तेयार किया और हमारी आयतों को झुठलाया तो वही जहन्नुमी हैं और हमेशा दोज़ख़ में पड़े रहेगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,40,'Al-Baqara','يَٰبَنِيٓ إِسۡرَٰٓءِيلَ ٱذۡكُرُواْ نِعۡمَتِيَ ٱلَّتِيٓ أَنۡعَمۡتُ عَلَيۡكُمۡ وَأَوۡفُواْ بِعَهۡدِيٓ أُوفِ بِعَهۡدِكُمۡ وَإِيَّٰيَ فَٱرۡهَبُونِ','اے یعقوب کی اولاد! میرے وہ احسان یاد کرو جو میں نے تم پر کئے تھے اور اس اقرار کو پورا کرو جو تم نے مجھ سے کیا تھا۔ میں اس اقرار کو پورا کروں گا جو میں نے تم سے کیا تھا اور مجھی سے ڈرتے رہو','O children of Israel! Remember My favours upon you. Fulfil your covenant and I will fulfil Mine, and stand in awe of Me ˹alone˺','ऐ बनी इसराईल (याक़ूब की औलाद) मेरे उन एहसानात को याद करो जो तुम पर पहले कर चुके हैं और तुम मेरे एहद व इक़रार (ईमान) को पूरा करो तो मैं तुम्हारे एहद (सवाब) को पूरा करूँगा, और मुझ ही से डरते रहो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,41,'Al-Baqara','وَءَامِنُواْ بِمَآ أَنزَلۡتُ مُصَدِّقࣰ ا لِّمَا مَعَكُمۡ وَلَا تَكُونُوٓاْ أَوَّلَ كَافِرِۭ بِهِۦۖ وَلَا تَشۡتَرُواْ بِـَٔايَٰتِي ثَمَنࣰ ا قَلِيلࣰ ا وَإِيَّٰيَ فَٱتَّقُونِ','اور جو کتاب میں نے (اپنے رسول محمدﷺ پر) نازل کی ہے جو تمہاری کتاب تورات کو سچا کہتی ہے، اس پر ایمان لاؤ اور اس سے منکرِ اول نہ بنو، اور میری آیتوں میں (تحریف کر کے) ان کے بدلے تھوڑی سی قیمت (یعنی دنیاوی منعفت) نہ حاصل کرو، اور مجھی سے خوف رکھو','Believe in My revelations which confirm your Scriptures. Do not be the first to deny them or trade them for a fleeting gain. And be mindful of Me','और जो (कुरान) मैंने नाज़िल किया वह उस किताब (तौरेत) की (भी) तसदीक़ करता हूँ जो तुम्हारे पास है और तुम सबसे चले उसके इन्कार पर मौजूद न हो जाओ और मेरी आयतों के बदले थोड़ी क़ीमत (दुनयावी फायदा) न लो और मुझ ही से डरते रहो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,42,'Al-Baqara','وَلَا تَلۡبِسُواْ ٱلۡحَقَّ بِٱلۡبَٰطِلِ وَتَكۡتُمُواْ ٱلۡحَقَّ وَأَنتُمۡ تَعۡلَمُونَ','اور حق کو باطل کے ساتھ نہ ملاؤ، اور سچی بات کو جان بوجھ کر نہ چھپاؤ','Do not mix truth with falsehood or hide the truth knowingly','और हक़ को बातिल के साथ न मिलाओ और हक़ बात को न छिपाओ हालाँकि तुम जानते हो और पाबन्दी से नमाज़ अदा करो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,43,'Al-Baqara','وَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ وَٱرۡكَعُواْ مَعَ ٱلرَّٰكِعِينَ','اور نماز پڑھا کرو اور زکوٰة دیا کرو اور (خدا کے آگے) جھکنے والوں کے ساتھ جھکا کرو','Establish prayer, pay alms-tax, and bow down with those who bow down','और ज़कात दिया करो और जो लोग (हमारे सामने) इबादत के लिए झुकते हैं उनके साथ तुम भी झुका करो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,44,'Al-Baqara','۞أَتَأۡمُرُونَ ٱلنَّاسَ بِٱلۡبِرِّ وَتَنسَوۡنَ أَنفُسَكُمۡ وَأَنتُمۡ تَتۡلُونَ ٱلۡكِتَٰبَۚ أَفَلَا تَعۡقِلُونَ','(یہ) کیا (عقل کی بات ہے کہ) تم لوگوں کو نیکی کرنے کو کہتے ہو اور اپنے تئیں فراموش کئے دیتے ہو، حالانکہ تم کتاب (خدا) بھی پڑھتے ہو۔ کیا تم سمجھتے نہیں؟','Do you preach righteousness and fail to practice it yourselves, although you read the Scripture? Do you not understand','और तुम लोगों से नेकी करने को कहते हो और अपनी ख़बर नहीं लेते हालाँकि तुम किताबे खुदा को (बराबर) रटा करते हो तो तुम क्या इतना भी नहीं समझते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,45,'Al-Baqara','وَٱسۡتَعِينُواْ بِٱلصَّبۡرِ وَٱلصَّلَوٰةِۚ وَإِنَّهَا لَكَبِيرَةٌ إِلَّا عَلَى ٱلۡخَٰشِعِينَ','اور (رنج وتکلیف میں) صبر اور نماز سے مدد لیا کرو اور بے شک نماز گراں ہے، مگر ان لوگوں پر (گراں نہیں) جو عجز کرنے والے ہیں','And seek help through patience and prayer. Indeed, it is a burden except for the humble—','और (मुसीबत के वक्त) सब्र और नमाज़ का सहारा पकड़ो और अलबत्ता नमाज़ दूभर तो है मगर उन ख़ाक़सारों पर (नहीं) जो बख़ूबी जानते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,46,'Al-Baqara','ٱلَّذِينَ يَظُنُّونَ أَنَّهُم مُّلَٰقُواْ رَبِّهِمۡ وَأَنَّهُمۡ إِلَيۡهِ رَٰجِعُونَ','اور جو یقین کئے ہوئے ہیں کہ وہ اپنے پروردگار سے ملنے والے ہیں اور اس کی طرف لوٹ کر جانے والے ہیں','those who are certain that they will meet their Lord and to Him they will return','कि वह अपने परवरदिगार की बारगाह में हाज़िर होंगे और ज़रूर उसकी तरफ लौट जाएँगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,47,'Al-Baqara','يَٰبَنِيٓ إِسۡرَٰٓءِيلَ ٱذۡكُرُواْ نِعۡمَتِيَ ٱلَّتِيٓ أَنۡعَمۡتُ عَلَيۡكُمۡ وَأَنِّي فَضَّلۡتُكُمۡ عَلَى ٱلۡعَٰلَمِينَ','اے یعقوب کی اولاد! میرے وہ احسان یاد کرو، جو میں نے تم پر کئے تھے اور یہ کہ میں نے تم کو جہان کے لوگوں پر فضیلت بخشی تھی','O Children of Israel! Remember ˹all˺ the favours I granted you and how I honoured you above the others','ऐ बनी इसराइल मेरी उन नेअमतों को याद करो जो मैंने पहले तुम्हें दी और ये (भी तो सोचो) कि हमने तुमको सारे जहान के लोगों से बढ़ा दिया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,48,'Al-Baqara','وَٱتَّقُواْ يَوۡمࣰ ا لَّا تَجۡزِي نَفۡسٌ عَن نَّفۡسࣲ شَيۡـࣰٔ ا وَلَا يُقۡبَلُ مِنۡهَا شَفَٰعَةࣱ وَلَا يُؤۡخَذُ مِنۡهَا عَدۡلࣱ وَلَا هُمۡ يُنصَرُونَ','اور اس دن سے ڈرو جب کوئی کسی کے کچھ کام نہ آئے اور نہ کسی کی سفارش منظور کی جائے اور نہ کسی سے کسی طرح کا بدلہ قبول کیا جائے اور نہ لوگ (کسی اور طرح) مدد حاصل کر سکیں','Guard yourselves against the Day on which no soul will be of help to another. No intercession will be accepted, no ransom taken, and no help will be given','और उस दिन से डरो (जिस दिन) कोई शख्स किसी की तरफ से न फिदिया हो सकेगा और न उसकी तरफ से कोई सिफारिश मानी जाएगी और न उसका कोई मुआवज़ा लिया जाएगा और न वह मदद पहुँचाए जाएँगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,49,'Al-Baqara','وَإِذۡ نَجَّيۡنَٰكُم مِّنۡ ءَالِ فِرۡعَوۡنَ يَسُومُونَكُمۡ سُوٓءَ ٱلۡعَذَابِ يُذَبِّحُونَ أَبۡنَآءَكُمۡ وَيَسۡتَحۡيُونَ نِسَآءَكُمۡۚ وَفِي ذَٰلِكُم بَلَآءࣱ مِّن رَّبِّكُمۡ عَظِيمࣱ‏','اور (ہمارے ان احسانات کو یاد کرو) جب ہم نے تم کو قومِ فرعون سے نجات بخشی وہ (لوگ) تم کو بڑا دکھ دیتے تھے تمہارے بیٹوں کو تو قتل کر ڈالتے تھے اور بیٹیوں کو زندہ رہنے دیتے تھے اور اس میں تمہارے پروردگار کی طرف سے بڑی (سخت) آزمائش تھی','˹Remember˺ how We delivered you from the people of Pharaoh, who afflicted you with dreadful torment, slaughtering your sons and keeping your women. That was a severe test from your Lord','और (उस वक्त क़ो याद करो) जब हमने तुम्हें (तुम्हारे बुर्ज़गो को) फिरऔन (के पन्जे) से छुड़ाया जो तुम्हें बड़े-बड़े दुख दे के सताते थे तुम्हारे लड़कों पर छुरी फेरते थे और तुम्हारी औरतों को (अपनी ख़िदमत के लिए) ज़िन्दा रहने देते थे और उसमें तुम्हारे परवरदिगार की तरफ से (तुम्हारे सब्र की) सख्त आज़माइश थी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,50,'Al-Baqara','وَإِذۡ فَرَقۡنَا بِكُمُ ٱلۡبَحۡرَ فَأَنجَيۡنَٰكُمۡ وَأَغۡرَقۡنَآ ءَالَ فِرۡعَوۡنَ وَأَنتُمۡ تَنظُرُونَ','اور جب ہم نے تمہارے لیے دریا کو پھاڑ دیا تم کو نجات دی اور فرعون کی قوم کو غرق کر دیا اور تم دیکھ ہی تو رہے تھے','And ˹remember˺ when We parted the sea, rescued you, and drowned Pharaoh’s people before your very eyes','और (वह वक्त भी याद करो) जब हमने तुम्हारे लिए दरिया को टुकड़े-टुकड़े किया फिर हमने तुमको छुटकारा दिया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,51,'Al-Baqara','وَإِذۡ وَٰعَدۡنَا مُوسَىٰٓ أَرۡبَعِينَ لَيۡلَةࣰ ثُمَّ ٱتَّخَذۡتُمُ ٱلۡعِجۡلَ مِنۢ بَعۡدِهِۦ وَأَنتُمۡ ظَٰلِمُونَ','اور جب ہم نے موسیٰ سے چالیس رات کا وعدہ کیا تو تم نے ان کے پیچھے بچھڑے کو (معبود) مقرر کر لیا اور تم ظلم کر رہے تھے','And ˹remember˺ when We appointed forty nights for Moses, then you worshipped the calf in his absence, acting wrongfully','और फिरऔन के आदमियों को तुम्हारे देखते-देखते डुबो दिया और (वह वक्त भी याद करो) जब हमने मूसा से चालीस रातों का वायदा किया था और तुम लोगों ने उनके जाने के बाद एक बछड़े को (परसतिश के लिए खुदा) बना लिया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,52,'Al-Baqara','ثُمَّ عَفَوۡنَا عَنكُم مِّنۢ بَعۡدِ ذَٰلِكَ لَعَلَّكُمۡ تَشۡكُرُونَ','پھر اس کے بعد ہم نے تم کو معاف کر دیا، تاکہ تم شکر کرو','Even then We ˹still˺ forgave you so perhaps you would be grateful','हालाँकि तुम अपने ऊपर ज़ुल्म जोत रहे थे फिर हमने उसके बाद भी दरगुज़र की ताकि तुम शुक्र करो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,53,'Al-Baqara','وَإِذۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ وَٱلۡفُرۡقَانَ لَعَلَّكُمۡ تَهۡتَدُونَ','اور جب ہم نے موسیٰ کو کتاب اور معجزے عنایت کئے، تاکہ تم ہدایت حاصل کرو','And ˹remember˺ when We gave Moses the Scripture—the standard ˹to distinguish between right and wrong˺ that perhaps you would be ˹rightly˺ guided','और (वह वक्त भी याद करो) जब मूसा को (तौरेत) अता की और हक़ और बातिल को जुदा करनेवाला क़ानून (इनायत किया) ताके तुम हिदायत पाओ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,54,'Al-Baqara','وَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِهِۦ يَٰقَوۡمِ إِنَّكُمۡ ظَلَمۡتُمۡ أَنفُسَكُم بِٱتِّخَاذِكُمُ ٱلۡعِجۡلَ فَتُوبُوٓاْ إِلَىٰ بَارِئِكُمۡ فَٱقۡتُلُوٓاْ أَنفُسَكُمۡ ذَٰلِكُمۡ خَيۡرࣱ لَّكُمۡ عِندَ بَارِئِكُمۡ فَتَابَ عَلَيۡكُمۡۚ إِنَّهُۥ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ','اور جب موسیٰ نے اپنی قوم کے لوگوں سے کہا کہ بھائیو، تم نے بچھڑے کو (معبود) ٹھہرانے میں (بڑا) ظلم کیا ہے، تو اپنے پیدا کرنے والے کے آگے توبہ کرو اور اپنے تئیں ہلاک کر ڈالو۔ تمہارے خالق کے نزدیک تمہارے حق میں یہی بہتر ہے۔ پھر اس نے تمہارا قصور معاف کر دیا۔ وہ بے شک معاف کرنے والا (اور) صاحبِ رحم ہے','And ˹remember˺ when Moses said to his people, “O my people! Surely you have wronged yourselves by worshipping the calf, so turn in repentance to your Creator and execute ˹the calf-worshippers among˺ yourselves. That is best for you in the sight of your Creator.” Then He accepted your repentance. Surely He is the Accepter of Repentance, Most Merciful','और (वह वक्त भी याद करो) जब मूसा ने अपनी क़ौम से कहा कि ऐ मेरी क़ौम तुमने बछड़े को (ख़ुदा) बना के अपने ऊपर बड़ा सख्त जुल्म किया तो अब (इसके सिवा कोई चारा नहीं कि) तुम अपने ख़ालिक की बारगाह में तौबा करो और वह ये है कि अपने को क़त्ल कर डालो तुम्हारे परवरदिगार के नज़दीक तुम्हारे हक़ में यही बेहतर है, फिर जब तुमने ऐसा किया तो खुदा ने तुम्हारी तौबा क़ुबूल कर ली बेशक वह बड़ा मेहरबान माफ़ करने वाला है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,55,'Al-Baqara','وَإِذۡ قُلۡتُمۡ يَٰمُوسَىٰ لَن نُّؤۡمِنَ لَكَ حَتَّىٰ نَرَى ٱللَّهَ جَهۡرَةࣰ فَأَخَذَتۡكُمُ ٱلصَّٰعِقَةُ وَأَنتُمۡ تَنظُرُونَ','اور جب تم نے (موسیٰ) سے کہا کہ موسیٰ، جب تک ہم خدا کو سامنے نہ دیکھ لیں گے، تم پر ایمان نہیں لائیں گے، تو تم کو بجلی نے آ گھیرا اور تم دیکھ رہے تھے','And ˹remember˺ when you said, “O Moses! We will never believe you until we see Allah with our own eyes,” so a thunderbolt struck you while you were looking on','और (वह वक्त भी याद करो) जब तुमने मूसा से कहा था कि ऐ मूसा हम तुम पर उस वक्त तक ईमान न लाएँगे जब तक हम खुदा को ज़ाहिर बज़ाहिर न देख ले उस पर तुम्हें बिजली ने ले डाला, और तुम तकते ही रह गए');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,56,'Al-Baqara','ثُمَّ بَعَثۡنَٰكُم مِّنۢ بَعۡدِ مَوۡتِكُمۡ لَعَلَّكُمۡ تَشۡكُرُونَ','پھر موت آ جانے کے بعد ہم نے تم کو ازسرِ نو زندہ کر دیا، تاکہ احسان مانو','Then We brought you back to life after your death, so that perhaps you would be grateful','फिर तुम्हें तुम्हारे मरने के बाद हमने जिला उठाया ताकि तुम शुक्र करो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,57,'Al-Baqara','وَظَلَّلۡنَا عَلَيۡكُمُ ٱلۡغَمَامَ وَأَنزَلۡنَا عَلَيۡكُمُ ٱلۡمَنَّ وَٱلسَّلۡوَىٰۖ كُلُواْ مِن طَيِّبَٰتِ مَا رَزَقۡنَٰكُمۡۚ وَمَا ظَلَمُونَا وَلَٰكِن كَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ','اور بادل کا تم پر سایہ کئے رکھا اور (تمہارے لیے) من و سلویٰ اتارتے رہے کہ جو پاکیزہ چیزیں ہم نے تم کو عطا فرمائی ہیں، ان کو کھاؤ (پیو) مگر تمہارے بزرگوں نے ان نعمتوں کی کچھ قدر نہ جانی (اور) وہ ہمارا کچھ نہیں بگاڑتے تھے بلکہ اپنا ہی نقصان کرتے تھے','And ˹remember when˺ We shaded you with clouds and sent down to you manna and quails, ˹saying˺, “Eat from the good things We have provided for you.” The evildoers ˹certainly˺ did not wrong Us, but wronged themselves','और हमने तुम पर अब्र का साया किया और तुम पर मन व सलवा उतारा और (ये भी तो कह दिया था कि) जो सुथरी व नफीस रोज़िया तुम्हें दी हैं उन्हें शौक़ से खाओ, और उन लोगों ने हमारा तो कुछ बिगड़ा नहीं मगर अपनी जानों पर सितम ढाते रहे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,58,'Al-Baqara','وَإِذۡ قُلۡنَا ٱدۡخُلُواْ هَٰذِهِ ٱلۡقَرۡيَةَ فَكُلُواْ مِنۡهَا حَيۡثُ شِئۡتُمۡ رَغَدࣰ ا وَٱدۡخُلُواْ ٱلۡبَابَ سُجَّدࣰ ا وَقُولُواْ حِطَّةࣱ نَّغۡفِرۡ لَكُمۡ خَطَٰيَٰكُمۡۚ وَسَنَزِيدُ ٱلۡمُحۡسِنِينَ','اور جب ہم نے (ان سے) کہا کہ اس گاؤں میں داخل ہو جاؤ اور اس میں جہاں سے چاہو، خوب کھاؤ (پیو) اور (دیکھنا) دروازے میں داخل ہونا تو سجدہ کرنا اور حطة کہنا، ہم تمہارے گناہ معاف کر دیں گے اور نیکی کرنے والوں کو اور زیادہ دیں گے','And ˹remember˺ when We said, “Enter this city and eat freely from wherever you please; enter the gate with humility, saying, ‘Absolve us.’ We will forgive your sins and multiply the reward for the good-doers.”','और (वह वक्त भी याद करो) जब हमने तुमसे कहा कि इस गाँव (अरीहा) में जाओ और इसमें जहाँ चाहो फराग़त से खाओ (पियो) और दरवाज़े पर सजदा करते हुए और ज़बान से हित्ता बख्शिश कहते हुए आओ तो हम तुम्हारी ख़ता ये बख्श देगे और हम नेकी करने वालों की नेकी (सवाब) बढ़ा देगें');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,59,'Al-Baqara','فَبَدَّلَ ٱلَّذِينَ ظَلَمُواْ قَوۡلًا غَيۡرَ ٱلَّذِي قِيلَ لَهُمۡ فَأَنزَلۡنَا عَلَى ٱلَّذِينَ ظَلَمُواْ رِجۡزࣰ ا مِّنَ ٱلسَّمَآءِ بِمَا كَانُواْ يَفۡسُقُونَ','تو جو ظالم تھے، انہوں نے اس لفظ کو، جس کا ان کو حکم دیا تھا، بدل کر اس کی جگہ اور لفظ کہنا شروع کیا، پس ہم نے (ان) ظالموں پر آسمان سے عذاب نازل کیا، کیونکہ نافرمانیاں کئے جاتے تھے','But the wrongdoers changed the words they were commanded to say. So We sent down a punishment from the heavens upon them for their rebelliousness','तो जो बात उनसे कही गई थी उसे शरीरों ने बदलकर दूसरी बात कहनी शुरू कर दी तब हमने उन लोगों पर जिन्होंने शरारत की थी उनकी बदकारी की वजह से आसमानी बला नाज़िल की');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,60,'Al-Baqara','۞وَإِذِ ٱسۡتَسۡقَىٰ مُوسَىٰ لِقَوۡمِهِۦ فَقُلۡنَا ٱضۡرِب بِّعَصَاكَ ٱلۡحَجَرَۖ فَٱنفَجَرَتۡ مِنۡهُ ٱثۡنَتَا عَشۡرَةَ عَيۡنࣰ اۖ قَدۡ عَلِمَ كُلُّ أُنَاسࣲ مَّشۡرَبَهُمۡۖ كُلُواْ وَٱشۡرَبُواْ مِن رِّزۡقِ ٱللَّهِ وَلَا تَعۡثَوۡاْ فِي ٱلۡأَرۡضِ مُفۡسِدِينَ','اور جب موسیٰ نے اپنی قوم کے لیے (خدا سے) پانی مانگا تو ہم نے کہا کہ اپنی لاٹھی پتھر پر مارو۔ (انہوں نے لاٹھی ماری) تو پھر اس میں سے بارہ چشمے پھوٹ نکلے، اور تمام لوگوں نے اپنا اپنا گھاٹ معلوم کر (کے پانی پی) لیا۔ (ہم نے حکم دیا کہ) خدا کی (عطا فرمائی ہوئی) روزی کھاؤ اور پیو، مگر زمین میں فساد نہ کرتے پھرنا','And ˹remember˺ when Moses prayed for water for his people, We said, “Strike the rock with your staff.” Then twelve springs gushed out, ˹and˺ each tribe knew its drinking place. ˹We then said,˺ “Eat and drink of Allah’s provisions, and do not go about spreading corruption in the land.”','और (वह वक्त भी याद करो) जब मूसा ने अपनी क़ौम के लिए पानी माँगा तो हमने कहा (ऐ मूसा) अपनी लाठी पत्थर पर मारो (लाठी मारते ही) उसमें से बारह चश्में फूट निकले और सब लोगों ने अपना-अपना घाट बखूबी जान लिया और हमने आम इजाज़त दे दी कि खुदा की दी हुईरोज़ी से खाओ पियो और मुल्क में फसाद न करते फिरो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,61,'Al-Baqara','وَإِذۡ قُلۡتُمۡ يَٰمُوسَىٰ لَن نَّصۡبِرَ عَلَىٰ طَعَامࣲ وَٰحِدࣲ فَٱدۡعُ لَنَا رَبَّكَ يُخۡرِجۡ لَنَا مِمَّا تُنۢبِتُ ٱلۡأَرۡضُ مِنۢ بَقۡلِهَا وَقِثَّآئِهَا وَفُومِهَا وَعَدَسِهَا وَبَصَلِهَاۖ قَالَ أَتَسۡتَبۡدِلُونَ ٱلَّذِي هُوَ أَدۡنَىٰ بِٱلَّذِي هُوَ خَيۡرٌۚ ٱهۡبِطُواْ مِصۡرࣰ ا فَإِنَّ لَكُم مَّا سَأَلۡتُمۡۗ وَضُرِبَتۡ عَلَيۡهِمُ ٱلذِّلَّةُ وَٱلۡمَسۡكَنَةُ وَبَآءُو بِغَضَبࣲ مِّنَ ٱللَّهِۚ ذَٰلِكَ بِأَنَّهُمۡ كَانُواْ يَكۡفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَيَقۡتُلُونَ ٱلنَّبِيِّـۧنَ بِغَيۡرِ ٱلۡحَقِّۚ ذَٰلِكَ بِمَا عَصَواْ وَّكَانُواْ يَعۡتَدُونَ','اور جب تم نے کہا کہ موسیٰ! ہم سے ایک (ہی) کھانے پر صبر نہیں ہو سکتا تو اپنے پروردگار سے دعا کیجئے کہ ترکاری اور ککڑی اور گیہوں اور مسور اور پیاز (وغیرہ) جو نباتات زمین سے اُگتی ہیں، ہمارے لیے پیدا کر دے۔ انہوں نے کہا کہ بھلا عمدہ چیزیں چھوڑ کر ان کے عوض ناقص چیزیں کیوں چاہتے ہوں۔ (اگر یہی چیزیں مطلوب ہیں) تو کسی شہر میں جا اترو، وہاں جو مانگتے ہو، مل جائے گا۔ اور (آخرکار) ذلت (ورسوائی) اور محتاجی (وبے نوائی) ان سے چمٹا دی گئی اور وہ الله کے غضب میں گرفتار ہو گئے۔ یہ اس لیے کہ وہ الله کی آیتوں سے انکار کرتے تھے اور (اس کے) نبیوں کو ناحق قتل کر دیتے تھے۔ (یعنی) یہ اس لیے کہ نافرمانی کئے جاتے اور حد سے بڑھے جاتے تھے','And ˹remember˺ when you said, “O Moses! We cannot endure the same meal ˹every day˺. So ˹just˺ call upon your Lord on our behalf, He will bring forth for us some of what the earth produces of herbs, cucumbers, garlic, lentils, and onions.” Moses scolded ˹them˺, “Do you exchange what is better for what is worse? ˹You can˺ go down to any village and you will find what you have asked for.” They were stricken with disgrace and misery, and they invited the displeasure of Allah for rejecting Allah’s signs and unjustly killing the prophets. This is ˹a fair reward˺ for their disobedience and violations','(और वह वक्त भी याद करो) जब तुमने मूसा से कहा कि ऐ मूसा हमसे एक ही खाने पर न रहा जाएगा तो आप हमारे लिए अपने परवरदिगार से दुआ कीजिए कि जो चीज़े ज़मीन से उगती है जैसे साग पात तरकारी और ककड़ी और गेहूँ या (लहसुन) और मसूर और प्याज़ (मन व सलवा) की जगह पैदा करें (मूसा ने) कहा क्या तुम ऐसी चीज़ को जो हर तरह से बेहतर है अदना चीज़ से बदलन चाहते हो तो किसी शहर में उतर पड़ो फिर तुम्हारे लिए जो तुमने माँगा है सब मौजूद है और उन पर रूसवाई और मोहताजी की मार पड़ी और उन लोगों ने क़हरे खुदा की तरफ पलटा खाया, ये सब इस सबब से हुआ कि वह लोग खुदा की निशानियों से इन्कार करते थे और पैग़म्बरों को नाहक शहीद करते थे, और इस वजह से (भी) कि वह नाफ़रमानी और सरकशी किया करते थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,62,'Al-Baqara','إِنَّ ٱلَّذِينَ ءَامَنُواْ وَٱلَّذِينَ هَادُواْ وَٱلنَّصَٰرَىٰ وَٱلصَّٰبِـِٔينَ مَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَعَمِلَ صَٰلِحࣰ ا فَلَهُمۡ أَجۡرُهُمۡ عِندَ رَبِّهِمۡ وَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ','جو لوگ مسلمان ہیں یا یہودی یا عیسائی یا ستارہ پرست، (یعنی کوئی شخص کسی قوم و مذہب کا ہو) جو خدا اور روز قیامت پر ایمان لائے گا، اور نیک عمل کرے گا، تو ایسے لوگوں کو ان (کے اعمال) کا صلہ خدا کے ہاں ملے گا اور (قیامت کے دن) ان کو نہ کسی طرح کا خوف ہوگا اور نہ وہ غم ناک ہوں گے','Indeed, the believers, Jews, Christians, and Sabians—whoever ˹truly˺ believes in Allah and the Last Day and does good will have their reward with their Lord. And there will be no fear for them, nor will they grieve','बेशक मुसलमानों और यहूदियों और नसरानियों और ला मज़हबों में से जो कोई खुदा और रोज़े आख़िरत पर ईमान लाए और अच्छे-अच्छे काम करता रहे तो उन्हीं के लिए उनका अज्र व सवाब उनके खुदा के पास है और न (क़यामत में) उन पर किसी का ख़ौफ होगा न वह रंजीदा दिल होंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,63,'Al-Baqara','وَإِذۡ أَخَذۡنَا مِيثَٰقَكُمۡ وَرَفَعۡنَا فَوۡقَكُمُ ٱلطُّورَ خُذُواْ مَآ ءَاتَيۡنَٰكُم بِقُوَّةࣲ وَٱذۡكُرُواْ مَا فِيهِ لَعَلَّكُمۡ تَتَّقُونَ','اور جب ہم نے تم سے عہد (کر) لیا اور کوہِ طُور کو تم پر اٹھا کھڑا کیا (اور حکم دیا) کہ جو کتاب ہم نے تم کو دی ہے، اس کو زور سے پکڑے رہو، اور جو اس میں (لکھا) ہے، اسے یاد رکھو، تاکہ (عذاب سے) محفوظ رہو','And ˹remember˺ when We took a covenant from you and raised the mountain above you ˹saying˺, “Hold firmly to that ˹Scripture˺ which We have given you and observe its teachings so perhaps you will become mindful ˹of Allah˺.”','और (वह वक्त याद करो) जब हमने (तामीले तौरेत) का तुमसे एक़रार कर लिया और हमने तुम्हारे सर पर तूर से (पहाड़ को) लाकर लटकाया और कह दिया कि तौरेत जो हमने तुमको दी है उसको मज़बूत पकड़े रहो और जो कुछ उसमें है उसको याद रखो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,64,'Al-Baqara','ثُمَّ تَوَلَّيۡتُم مِّنۢ بَعۡدِ ذَٰلِكَۖ فَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُۥ لَكُنتُم مِّنَ ٱلۡخَٰسِرِينَ','تو تم اس کے بعد (عہد سے) پھر گئے اور اگر تم پر خدا کا فضل اور اس کی مہربانی نہ ہوتی تو تم خسارے میں پڑے گئے ہوتے','Yet you turned away afterwards. Had it not been for Allah’s grace and mercy upon you, you would have certainly been of the losers','ताकि तुम परहेज़गार बनो फिर उसके बाद तुम (अपने एहदो पैमान से) फिर गए पस अगर तुम पर खुदा का फज़ल और उसकी मेहरबानी न होती तो तुमने सख्त घाटा उठाया होता');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,65,'Al-Baqara','وَلَقَدۡ عَلِمۡتُمُ ٱلَّذِينَ ٱعۡتَدَوۡاْ مِنكُمۡ فِي ٱلسَّبۡتِ فَقُلۡنَا لَهُمۡ كُونُواْ قِرَدَةً خَٰسِـِٔينَ','اور تم ان لوگوں کو خوب جانتے ہوں، جو تم میں سے ہفتے کے دن (مچھلی کا شکار کرنے) میں حد سے تجاوز کر گئے تھے، تو ہم نے ان سے کہا کہ ذلیل وخوار بندر ہو جاؤ','You are already aware of those of you who broke the Sabbath. We said to them, “Be disgraced apes!”','और अपनी क़ौम से उन लोगों की हालत तो तुम बखूबी जानते हो जो शम्बे (सनीचर) के दिन अपनी हद से गुज़र गए (कि बावजूद मुमानिअत शिकार खेलने निकले) तो हमने उन से कहा कि तुम राइन्दे गए बन्दर बन जाओ (और वह बन्दर हो गए)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,66,'Al-Baqara','فَجَعَلۡنَٰهَا نَكَٰلࣰ ا لِّمَا بَيۡنَ يَدَيۡهَا وَمَا خَلۡفَهَا وَمَوۡعِظَةࣰ لِّلۡمُتَّقِينَ','اور اس قصے کو اس وقت کے لوگوں کے لیے اور جو ان کے بعد آنے والے تھے عبرت اور پرہیز گاروں کے لیے نصیحت بنا دیا','So We made their fate an example to present and future generations, and a lesson to the God-fearing','पस हमने इस वाक़ये से उन लोगों के वास्ते जिन के सामने हुआ था और जो उसके बाद आनेवाले थे अज़ाब क़रार दिया, और परहेज़गारों के लिए नसीहत');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,67,'Al-Baqara','وَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِهِۦٓ إِنَّ ٱللَّهَ يَأۡمُرُكُمۡ أَن تَذۡبَحُواْ بَقَرَةࣰۖ قَالُوٓاْ أَتَتَّخِذُنَا هُزُوࣰ اۖ قَالَ أَعُوذُ بِٱللَّهِ أَنۡ أَكُونَ مِنَ ٱلۡجَٰهِلِينَ','اور جب موسیٰ نے اپنی قوم کے لوگوں سے کہا کہ خدا تم کو حکم دیتا ہے کہ ایک بیل ذبح کرو۔ وہ بولے، کیا تم ہم سے ہنسی کرتے ہو۔ (موسیٰ نے) کہا کہ میں الله کی پناہ مانگتا ہوں کہ نادان بنوں','And ˹remember˺ when Moses said to his people, “Allah commands you to sacrifice a cow.” They replied, “Are you mocking us?” Moses responded, “I seek refuge in Allah from acting foolishly!”','और (वह वक्त याद करो) जब मूसा ने अपनी क़ौम से कहा कि खुदा तुम लोगों को ताकीदी हुक्म करता है कि तुम एक गाय ज़िबाह करो वह लोग कहने लगे क्या तुम हमसे दिल्लगी करते हो मूसा ने कहा मैं खुदा से पनाह माँगता हूँ कि मैं जाहिल बनूँ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,68,'Al-Baqara','قَالُواْ ٱدۡعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِيَۚ قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةࣱ لَّا فَارِضࣱ وَلَا بِكۡرٌ عَوَانُۢ بَيۡنَ ذَٰلِكَۖ فَٱفۡعَلُواْ مَا تُؤۡمَرُونَ','انہوں نے کہا کہ اپنے پروردگار سے التجا کیجئے کہ وہ ہمیں یہ بتائے کہ وہ بیل کس طرح کا ہو۔ (موسیٰ نے) کہا کہ پروردگار فرماتا ہے کہ وہ بیل نہ تو بوڑھا ہو اور نہ بچھڑا، بلکہ ان کے درمیان (یعنی جوان) ہو۔ جیسا تم کو حکم دیا گیا ہے، ویسا کرو','They said, “Call upon your Lord to clarify for us what type ˹of cow˺ it should be!” He replied, “Allah says, ‘The cow should neither be old nor young but in between. So do as you are commanded!’”','तब वह लोग कहने लगे कि (अच्छा) तुम अपने खुदा से दुआ करो कि हमें बता दे कि वह गाय कैसी हो मूसा ने कहा बेशक खुदा ने फरमाता है कि वह गाय न तो बहुत बूढ़ी हो और न बछिया बल्कि उनमें से औसत दरजे की हो, ग़रज़ जो तुमको हुक्म दिया गया उसको बजा लाओ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,69,'Al-Baqara','قَالُواْ ٱدۡعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا لَوۡنُهَاۚ قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةࣱ صَفۡرَآءُ فَاقِعࣱ لَّوۡنُهَا تَسُرُّ ٱلنَّٰظِرِينَ','انہوں نے کہا کہ پروردگار سے درخواست کیجئے کہ ہم کو یہ بھی بتائے کہ اس کا رنگ کیسا ہو۔ موسیٰ نے کہا، پروردگار فرماتا ہے کہ اس کا رنگ گہرا زرد ہو کہ دیکھنے والوں (کے دل) کو خوش کر دیتا ہو','They said, “Call upon your Lord to specify for us its colour.” He replied, “Allah says, ‘It should be a bright yellow cow—pleasant to see.’”','वह कहने लगे (वाह) तुम अपने खुदा से दुआ करो कि हमें ये बता दे कि उसका रंग आख़िर क्या हो मूसा ने कहा बेशक खुदा फरमाता है कि वह गाय खूब गहरे ज़र्द रंग की हो देखने वाले उसे देखकर खुश हो जाए');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,70,'Al-Baqara','قَالُواْ ٱدۡعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِيَ إِنَّ ٱلۡبَقَرَ تَشَٰبَهَ عَلَيۡنَا وَإِنَّآ إِن شَآءَ ٱللَّهُ لَمُهۡتَدُونَ','انہوں نے کہا کہ (اب کے) پروردگار سے پھر درخواست کیجئے کہ ہم کو بتا دے کہ وہ اور کس کس طرح کا ہو، کیونکہ بہت سے بیل ہمیں ایک دوسرے کے مشابہ معلوم ہوتے ہیں، (پھر) خدا نے چاہا تو ہمیں ٹھیک بات معلوم ہو جائے گی','Again they said, “Call upon your Lord so that He may make clear to us which cow, for all cows look the same to us. Then, Allah willing, we will be guided ˹to the right one˺.”','तब कहने लगे कि तुम अपने खुदा से दुआ करो कि हमें ज़रा ये तो बता दे कि वह (गाय) और कैसी हो (वह) गाय तो और गायों में मिल जुल गई और खुदा ने चाहा तो हम ज़रूर (उसका) पता लगा लेगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,71,'Al-Baqara','قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةࣱ لَّا ذَلُولࣱ تُثِيرُ ٱلۡأَرۡضَ وَلَا تَسۡقِي ٱلۡحَرۡثَ مُسَلَّمَةࣱ لَّا شِيَةَ فِيهَاۚ قَالُواْ ٱلۡـَٰٔنَ جِئۡتَ بِٱلۡحَقِّۚ فَذَبَحُوهَا وَمَا كَادُواْ يَفۡعَلُونَ','موسیٰ نے کہا کہ خدا فرماتا ہے کہ وہ بیل کام میں لگا ہوا نہ ہو، نہ تو زمین جوتتا ہو اور نہ کھیتی کو پانی دیتا ہو۔ اس میں کسی طرح کا داغ نہ ہو۔ کہنے لگے، اب تم نے سب باتیں درست بتا دیں۔ غرض (بڑی مشکل سے) انہوں نے اس بیل کو ذبح کیا، اور وہ ایسا کرنے والے تھے نہیں','He replied, “Allah says, ‘It should have been used neither to till the soil nor water the fields; wholesome and without blemish.’” They said, “Now you have come with the truth.” Yet they still slaughtered it hesitantly','मूसा ने कहा खुदा ज़रूर फरमाता है कि वह गाय न तो इतनी सधाई हो कि ज़मीन जोते न खेती सीचें भली चंगी एक रंग की कि उसमें कोई धब्बा तक न हो, वह बोले अब (जा के) ठीक-ठीक बयान किया, ग़रज़ उन लोगों ने वह गाय हलाल की हालाँकि उनसे उम्मीद न थी वह कि वह ऐसा करेंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,72,'Al-Baqara','وَإِذۡ قَتَلۡتُمۡ نَفۡسࣰ ا فَٱدَّٰرَٰٔتُمۡ فِيهَاۖ وَٱللَّهُ مُخۡرِجࣱ مَّا كُنتُمۡ تَكۡتُمُونَ','اور جب تم نے ایک شخص کو قتل کیا، تو اس میں باہم جھگڑنے لگے۔ لیکن جو بات تم چھپا رہے تھے، خدا اس کو ظاہر کرنے والا تھا','˹This is˺ when a man was killed and you disputed who the killer was, but Allah revealed what you concealed','और जब एक शख्स को मार डाला और तुममें उसकी बाबत फूट पड़ गई एक दूसरे को क़ातिल बताने लगा जो तुम छिपाते थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,73,'Al-Baqara','فَقُلۡنَا ٱضۡرِبُوهُ بِبَعۡضِهَاۚ كَذَٰلِكَ يُحۡيِ ٱللَّهُ ٱلۡمَوۡتَىٰ وَيُرِيكُمۡ ءَايَٰتِهِۦ لَعَلَّكُمۡ تَعۡقِلُونَ','تو ہم نے کہا کہ اس بیل کا کوئی سا ٹکڑا مقتول کو مارو۔ اس طرح خدا مردوں کو زندہ کرتا ہے اور تم کو اپنی (قدرت کی) نشانیاں دکھاتا ہے تاکہ تم سمجھو','So We instructed, “Strike the dead body with a piece of the cow.” This is how ˹easily˺ Allah brings the dead to life, showing you His signs so that you may understand','खुदा को उसका ज़ाहिर करना मंजूर था पस हमने कहा कि उस गाय को कोई टुकड़ा लेकर इस (की लाश) पर मारो यूँ खुदा मुर्दे को ज़िन्दा करता है और तुम को अपनी कुदरत की निशानियाँ दिखा देता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,74,'Al-Baqara','ثُمَّ قَسَتۡ قُلُوبُكُم مِّنۢ بَعۡدِ ذَٰلِكَ فَهِيَ كَٱلۡحِجَارَةِ أَوۡ أَشَدُّ قَسۡوَةࣰۚ وَإِنَّ مِنَ ٱلۡحِجَارَةِ لَمَا يَتَفَجَّرُ مِنۡهُ ٱلۡأَنۡهَٰرُۚ وَإِنَّ مِنۡهَا لَمَا يَشَّقَّقُ فَيَخۡرُجُ مِنۡهُ ٱلۡمَآءُۚ وَإِنَّ مِنۡهَا لَمَا يَهۡبِطُ مِنۡ خَشۡيَةِ ٱللَّهِۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعۡمَلُونَ','پھر اس کے بعد تمہارے دل سخت ہو گئے۔ گویا وہ پتھر ہیں یا ان سے بھی زیادہ سخت۔ اور پتھر تو بعضے ایسے ہوتے ہیں کہ ان میں سے چشمے پھوٹ نکلتے ہیں، اور بعضے ایسے ہوتے ہیں کہ پھٹ جاتے ہیں، اور ان میں سے پانی نکلنے لگتا ہے، اور بعضے ایسے ہوتے ہیں کہ خدا کے خوف سے گر پڑتے ہیں، اور خدا تمہارے عملوں سے بے خبر نہیں','Even then your hearts became hardened like a rock or even harder, for some rocks gush rivers; others split, spilling water; while others are humbled in awe of Allah. And Allah is never unaware of what you do','ताकि तुम समझो फिर उसके बाद तुम्हारे दिल सख्त हो गये पस वह मिसल पत्थर के (सख्त) थे या उससे भी ज्यादा करख्त क्योंकि पत्थरों में बाज़ तो ऐसे होते हैं कि उनसे नहरें जारी हो जाती हैं और बाज़ ऐसे होते हैं कि उनमें दरार पड़ जाती है और उनमें से पानी निकल पड़ता है और बाज़ पत्थर तो ऐसे होते हैं कि खुदा के ख़ौफ से गिर पड़ते हैं और जो कुछ तुम कर रहे हो उससे खुदा ग़ाफिल नहीं है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,75,'Al-Baqara','۞أَفَتَطۡمَعُونَ أَن يُؤۡمِنُواْ لَكُمۡ وَقَدۡ كَانَ فَرِيقࣱ مِّنۡهُمۡ يَسۡمَعُونَ كَلَٰمَ ٱللَّهِ ثُمَّ يُحَرِّفُونَهُۥ مِنۢ بَعۡدِ مَا عَقَلُوهُ وَهُمۡ يَعۡلَمُونَ','(مومنو) کیا تم امید رکھتے ہو کہ یہ لوگ تمہارے (دین کے) قائل ہو جائیں گے، (حالانکہ) ان میں سے کچھ لوگ کلامِ خدا (یعنی تورات) کو سنتے، پھر اس کے سمجھ لینے کے بعد اس کو جان بوجھ کر بدل دیتے رہے ہیں','Do you ˹believers still˺ expect them to be true to you, though a group of them would hear the word of Allah then knowingly corrupt it after understanding it','(मुसलमानों) क्या तुम ये लालच रखते हो कि वह तुम्हारा (सा) ईमान लाएँगें हालाँकि उनमें का एक गिरोह (साबिक़ में) ऐसा था कि खुदा का कलाम सुनाता था और अच्छी तरह समझने के बाद उलट फेर कर देता था हालाँकि वह खूब जानते थे और जब उन लोगों से मुलाक़ात करते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,76,'Al-Baqara','وَإِذَا لَقُواْ ٱلَّذِينَ ءَامَنُواْ قَالُوٓاْ ءَامَنَّا وَإِذَا خَلَا بَعۡضُهُمۡ إِلَىٰ بَعۡضࣲ قَالُوٓاْ أَتُحَدِّثُونَهُم بِمَا فَتَحَ ٱللَّهُ عَلَيۡكُمۡ لِيُحَآجُّوكُم بِهِۦ عِندَ رَبِّكُمۡۚ أَفَلَا تَعۡقِلُونَ','اور یہ لوگ جب مومنوں سے ملتے ہیں تو کہتے ہیں، ہم ایمان لے آئے ہیں۔ اور جب آپس میں ایک دوسرے سے ملتے ہیں تو کہتے ہیں، جو بات خدا نے تم پر ظاہر فرمائی ہے، وہ تم ان کو اس لیے بتائے دیتے ہو کہ (قیامت کے دن) اسی کے حوالے سے تمہارے پروردگار کے سامنے تم کو الزام دیں۔ کیا تم سمجھتے نہیں؟','When they meet the believers they say, “We believe.” But in private they say ˹to each other˺, “Will you disclose to the believers the knowledge Allah has revealed to you, so that they may use it against you before your Lord? Do you not understand?”','जो ईमान लाए तो कह देते हैं कि हम तो ईमान ला चुके और जब उनसे बाज़-बाज़ के साथ तख़िलया करते हैं तो कहते हैं कि जो कुछ खुदा ने तुम पर (तौरेत) में ज़ाहिर कर दिया है क्या तुम (मुसलमानों को) बता दोगे ताकि उसके सबब से कल तुम्हारे खुदा के पास तुम पर हुज्जत लाएँ क्या तुम इतना भी नहीं समझते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,77,'Al-Baqara','أَوَلَا يَعۡلَمُونَ أَنَّ ٱللَّهَ يَعۡلَمُ مَا يُسِرُّونَ وَمَا يُعۡلِنُونَ','کیا یہ لوگ یہ نہیں جانتے کہ جو کچھ یہ چھپاتے اور جو کچھ ظاہر کرتے ہیں، خدا کو (سب) معلوم ہے','Do they not know that Allah is aware of what they conceal and what they reveal','लेकिन क्या वह लोग (इतना भी) नहीं जानते कि वह लोग जो कुछ छिपाते हैं या ज़ाहिर करते हैं खुदा सब कुछ जानता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,78,'Al-Baqara','وَمِنۡهُمۡ أُمِّيُّونَ لَا يَعۡلَمُونَ ٱلۡكِتَٰبَ إِلَّآ أَمَانِيَّ وَإِنۡ هُمۡ إِلَّا يَظُنُّونَ','اور بعض ان میں ان پڑھ ہیں کہ اپنے باطل خیالات کے سوا (خدا کی) کتاب سے واقف ہی نہیں اور وہ صرف ظن سے کام لیتے ہیں','And among them are the illiterate who know nothing about the Scripture except lies, and ˹so˺ they ˹wishfully˺ speculate','और कुछ उनमें से ऐसे अनपढ़ हैं कि वह किताबे खुदा को अपने मतलब की बातों के सिवा कुछ नहीं समझते और वह फक़त ख्याली बातें किया करते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,79,'Al-Baqara','فَوَيۡلࣱ لِّلَّذِينَ يَكۡتُبُونَ ٱلۡكِتَٰبَ بِأَيۡدِيهِمۡ ثُمَّ يَقُولُونَ هَٰذَا مِنۡ عِندِ ٱللَّهِ لِيَشۡتَرُواْ بِهِۦ ثَمَنࣰ ا قَلِيلࣰ اۖ فَوَيۡلࣱ لَّهُم مِّمَّا كَتَبَتۡ أَيۡدِيهِمۡ وَوَيۡلࣱ لَّهُم مِّمَّا يَكۡسِبُونَ','تو ان لوگوں پر افسوس ہے جو اپنے ہاتھ سے تو کتاب لکھتے ہیں اور کہتے یہ ہیں کہ یہ خدا کے پاس سے (آئی) ہے، تاکہ اس کے عوض تھوڑی سے قیمت (یعنی دنیوی منفعت) حاصل کریں۔ ان پر افسوس ہے، اس لیے کہ (بےاصل باتیں) اپنے ہاتھ سے لکھتے ہیں اور (پھر) ان پر افسوس ہے، اس لیے کہ ایسے کام کرتے ہیں','So woe to those who distort the Scripture with their own hands then say, “This is from Allah”—seeking a fleeting gain! So woe to them for what their hands have written, and woe to them for what they have earned','पस वाए हो उन लोगों पर जो अपने हाथ से किताब लिखते हैं फिर (लोगों से कहते फिरते) हैं कि ये खुदा के यहाँ से (आई) है ताकि उसके ज़रिये से थोड़ी सी क़ीमत (दुनयावी फ़ायदा) हासिल करें पस अफसोस है उन पर कि उनके हाथों ने लिखा और फिर अफसोस है उनपर कि वह ऐसी कमाई करते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,80,'Al-Baqara','وَقَالُواْ لَن تَمَسَّنَا ٱلنَّارُ إِلَّآ أَيَّامࣰ ا مَّعۡدُودَةࣰۚ قُلۡ أَتَّخَذۡتُمۡ عِندَ ٱللَّهِ عَهۡدࣰ ا فَلَن يُخۡلِفَ ٱللَّهُ عَهۡدَهُۥٓۖ أَمۡ تَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعۡلَمُونَ','اور کہتے ہیں کہ (دوزخ کی) آگ ہمیں چند روز کے سوا چھو ہی نہیں سکے گی۔ ان سے پوچھو، کیا تم نے خدا سے اقرار لے رکھا ہے کہ خدا اپنے اقرار کے خلاف نہیں کرے گا۔ (نہیں)، بلکہ تم خدا کے بارے میں ایسی باتیں کہتے ہو جن کا تمہیں مطلق علم نہیں','˹Some of˺ the Jews claim, “The Fire will not touch us except for a number of days.” Say, ˹O Prophet,˺ “Have you taken a pledge from Allah—for Allah never breaks His word—or are you ˹just˺ saying about Allah what you do not know?”','और कहते हैं कि गिनती के चन्द दिनों के सिवा हमें आग छुएगी भी तो नहीं (ऐ रसूल) इन लोगों से कहो कि क्या तुमने खुदा से कोई इक़रार ले लिया है कि फिर वह किसी तरह अपने इक़रार के ख़िलाफ़ हरगिज़ न करेगा या बे समझे बूझे खुदा पर बोहताव जोड़ते हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,81,'Al-Baqara','بَلَىٰۚ مَن كَسَبَ سَيِّئَةࣰ وَأَحَٰطَتۡ بِهِۦ خَطِيٓـَٔتُهُۥ فَأُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ','ہاں جو برے کام کرے، اور اس کے گناہ (ہر طرف سے) گھیر لیں تو ایسے لوگ دوزخ (میں جانے) والے ہیں (اور) وہ ہمیشہ اس میں (جلتے) رہیں گے','But no! Those who commit evil and are engrossed in sin will be the residents of the Fire. They will be there forever','हाँ (सच तो यह है) कि जिसने बुराई हासिल की और उसके गुनाहों ने चारों तरफ से उसे घेर लिया है वही लोग तो दोज़ख़ी हैं और वही (तो) उसमें हमेशा रहेंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,82,'Al-Baqara','وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلۡجَنَّةِۖ هُمۡ فِيهَا خَٰلِدُونَ','اور جو ایمان لائیں اور نیک کام کریں، وہ جنت کے مالک ہوں گے (اور) ہمیشہ اس میں (عیش کرتے) رہیں گے','And those who believe and do good will be the residents of Paradise. They will be there forever','और जो लोग ईमानदार हैं और उन्होंने अच्छे काम किए हैं वही लोग जन्नती हैं कि हमेशा जन्नत में रहेंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,83,'Al-Baqara','وَإِذۡ أَخَذۡنَا مِيثَٰقَ بَنِيٓ إِسۡرَٰٓءِيلَ لَا تَعۡبُدُونَ إِلَّا ٱللَّهَ وَبِٱلۡوَٰلِدَيۡنِ إِحۡسَانࣰ ا وَذِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينِ وَقُولُواْ لِلنَّاسِ حُسۡنࣰ ا وَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ ثُمَّ تَوَلَّيۡتُمۡ إِلَّا قَلِيلࣰ ا مِّنكُمۡ وَأَنتُم مُّعۡرِضُونَ','اور جب ہم نے بنی اسرائیل سے عہد لیا کہ خدا کے سوا کسی کی عبادت نہ کرنا اور ماں باپ اور رشتہ داروں اور یتیموں اور محتاجوں کے ساتھ بھلائی کرتے رہنا اور لوگوں سے اچھی باتیں کہنا، اور نماز پڑھتے اور زکوٰة دیتے رہنا، تو چند شخصوں کے سوا تم سب (اس عہد سے) منہ پھیر کر پھر بیٹھے','And ˹remember˺ when We took a covenant from the children of Israel ˹stating˺, “Worship none but Allah; be kind to parents, relatives, orphans and the needy; speak kindly to people; establish prayer; and pay alms-tax.” But you ˹Israelites˺ turned away—except for a few of you—and were indifferent','और (वह वक्त याद करो) जब हमने बनी ईसराइल से (जो तुम्हारे बुर्जुग़ थे) अहद व पैमान लिया था कि खुदा के सिवा किसी की इबादत न करना और माँ बाप और क़राबतदारों और यतीमों और मोहताजों के साथ अच्छे सुलूक करना और लोगों के साथ अच्छी तरह (नरमी) से बातें करना और बराबर नमाज़ पढ़ना और ज़कात देना फिर तुममें से थोड़े आदिमियों के सिवा (सब के सब) फिर गए और तुम लोग हो ही इक़रार से मुँह फेरने वाले');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,84,'Al-Baqara','وَإِذۡ أَخَذۡنَا مِيثَٰقَكُمۡ لَا تَسۡفِكُونَ دِمَآءَكُمۡ وَلَا تُخۡرِجُونَ أَنفُسَكُم مِّن دِيَٰرِكُمۡ ثُمَّ أَقۡرَرۡتُمۡ وَأَنتُمۡ تَشۡهَدُونَ','اور جب ہم نے تم سے عہد لیا کہ آپس میں کشت وخون نہ کرنا اور اپنے کو ان کے وطن سے نہ نکالنا تو تم نے اقرار کر لیا، اور تم (اس بات کے) گواہ ہو','And ˹remember˺ when We took your covenant that you would neither shed each other’s blood nor expel each other from their homes, you gave your pledge and bore witness','और (वह वक्त याद करो) जब हमने तुम (तुम्हारे बुर्ज़ुगों) से अहद लिया था कि आपस में खूरेज़ियाँ न करना और न अपने लोगों को शहर बदर करना तो तुम (तुम्हारे बुर्जुग़ों) ने इक़रार किया था और तुम भी उसकी गवाही देते हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,85,'Al-Baqara','ثُمَّ أَنتُمۡ هَٰٓؤُلَآءِ تَقۡتُلُونَ أَنفُسَكُمۡ وَتُخۡرِجُونَ فَرِيقࣰ ا مِّنكُم مِّن دِيَٰرِهِمۡ تَظَٰهَرُونَ عَلَيۡهِم بِٱلۡإِثۡمِ وَٱلۡعُدۡوَٰنِ وَإِن يَأۡتُوكُمۡ أُسَٰرَىٰ تُفَٰدُوهُمۡ وَهُوَ مُحَرَّمٌ عَلَيۡكُمۡ إِخۡرَاجُهُمۡۚ أَفَتُؤۡمِنُونَ بِبَعۡضِ ٱلۡكِتَٰبِ وَتَكۡفُرُونَ بِبَعۡضࣲۚ فَمَا جَزَآءُ مَن يَفۡعَلُ ذَٰلِكَ مِنكُمۡ إِلَّا خِزۡيࣱ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ وَيَوۡمَ ٱلۡقِيَٰمَةِ يُرَدُّونَ إِلَىٰٓ أَشَدِّ ٱلۡعَذَابِۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعۡمَلُونَ','پھر تم وہی ہو کہ اپنوں کو قتل بھی کر دیتے ہو اور اپنے میں سے بعض لوگوں پر گناہ اور ظلم سے چڑھائی کرکے انہیں وطن سے نکال بھی دیتے ہو، اور اگر وہ تمہارے پاس قید ہو کر آئیں تو بدلہ دے کر ان کو چھڑا بھی لیتے ہو، حالانکہ ان کا نکال دینا ہی تم کو حرام تھا۔ (یہ) کیا (بات ہے کہ) تم کتابِ (خدا) کے بعض احکام کو تو مانتے ہو اور بعض سے انکار کئے دیتے ہو، تو جو تم میں سے ایسی حرکت کریں، ان کی سزا اس کے سوا اور کیا ہو سکتی ہے کہ دنیا کی زندگی میں تو رسوائی ہو اور قیامت کے دن سخت سے سخت عذاب میں ڈال دیئے جائیں اور جو کام تم کرتے ہو، خدا ان سے غافل نہیں','But here you are, killing each other and expelling some of your people from their homes, aiding one another in sin and aggression; and when those ˹expelled˺ come to you as captives, you still ransom them—though expelling them was unlawful for you. Do you believe in some of the Scripture and reject the rest? Is there any reward for those who do so among you other than disgrace in this worldly life and being subjected to the harshest punishment on the Day of Judgment? For Allah is never unaware of what you do','(कि हाँ ऐसा हुआ था) फिर वही लोग तो तुम हो कि आपस में एक दूसरे को क़त्ल करते हो और अपनों से एक जत्थे के नाहक़ और ज़बरदस्ती हिमायती बनकर दूसरे को शहर बदर करते हो (और लुत्फ़ तो ये है कि) अगर वही लोग क़ैदी बनकर तम्हारे पास (मदद माँगने) आए तो उनको तावान देकर छुड़ा लेते हो हालाँकि उनका निकालना ही तुम पर हराम किया गया था तो फिर क्या तुम (किताबे खुदा की) बाज़ बातों पर ईमान रखते हो और बाज़ से इन्कार करते हो पस तुम में से जो लोग ऐसा करें उनकी सज़ा इसके सिवा और कुछ नहीं कि ज़िन्दगी भर की रूसवाई हो और (आख़िरकार) क़यामत के दिन सख्त अज़ाब की तरफ लौटा दिये जाए और जो कुछ तुम लोग करते हो खुदा उससे ग़ाफ़िल नहीं है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,86,'Al-Baqara','أُوْلَٰٓئِكَ ٱلَّذِينَ ٱشۡتَرَوُاْ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا بِٱلۡأٓخِرَةِۖ فَلَا يُخَفَّفُ عَنۡهُمُ ٱلۡعَذَابُ وَلَا هُمۡ يُنصَرُونَ','یہ وہ لوگ ہیں جنہوں نے آخرت کے بدلے دنیا کی زندگی خریدی۔ سو نہ تو ان سے عذاب ہی ہلکا کیا جائے گا اور نہ ان کو (اور طرح کی) مدد ملے گی','These are the ones who trade the Hereafter for the life of this world. So their punishment will not be reduced, nor will they be helped','यही वह लोग हैं जिन्होंने आख़ेरत के बदले दुनिया की ज़िन्दगी ख़रीद पस न उनके अज़ाब ही में तख्फ़ीफ़ (कमी) की जाएगी और न वह लोग किसी तरह की मदद दिए जाएँगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,87,'Al-Baqara','وَلَقَدۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ وَقَفَّيۡنَا مِنۢ بَعۡدِهِۦ بِٱلرُّسُلِۖ وَءَاتَيۡنَا عِيسَى ٱبۡنَ مَرۡيَمَ ٱلۡبَيِّنَٰتِ وَأَيَّدۡنَٰهُ بِرُوحِ ٱلۡقُدُسِۗ أَفَكُلَّمَا جَآءَكُمۡ رَسُولُۢ بِمَا لَا تَهۡوَىٰٓ أَنفُسُكُمُ ٱسۡتَكۡبَرۡتُمۡ فَفَرِيقࣰ ا كَذَّبۡتُمۡ وَفَرِيقࣰ ا تَقۡتُلُونَ','اور ہم نے موسیٰ کو کتاب عنایت کی اور ان کے پیچھے یکے بعد دیگرے پیغمبر بھیجتے رہے اور عیسیٰ بن مریم کو کھلے نشانات بخشے اور روح القدس (یعنی جبرئیل) سے ان کو مدد دی۔تو جب کوئی پیغمبر تمہارے پاس ایسی باتیں لے کر آئے، جن کو تمہارا جی نہیں چاہتا تھا، تو تم سرکش ہو جاتے رہے، اور ایک گروہ (انبیاء) کو تو جھٹلاتے رہے اور ایک گروہ کو قتل کرتے رہے','Indeed, We gave Moses the Book and sent after him successive messengers. And We gave Jesus, son of Mary, clear proofs and supported him with the holy spirit. Why is it that every time a messenger comes to you ˹Israelites˺ with something you do not like, you become arrogant, rejecting some and killing others','और ये हक़ीक़ी बात है कि हमने मूसा को किताब (तौरेत) दी और उनके बाद बहुत से पैग़म्बरों को उनके क़दम ब क़दम ले चलें और मरियम के बेटे ईसा को (भी बहुत से) वाजेए व रौशन मौजिजे दिए और पाक रूह जिबरील के ज़रिये से उनकी मदद की क्या तुम उस क़दर बददिमाग़ हो गए हो कि जब कोई पैग़म्बर तुम्हारे पास तुम्हारी ख्वाहिशे नफ़सानी के ख़िलाफ कोई हुक्म लेकर आया तो तुम अकड़ बैठे फिर तुमने बाज़ पैग़म्बरों को तो झुठलाया और बाज़ को जान से मार डाला');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,88,'Al-Baqara','وَقَالُواْ قُلُوبُنَا غُلۡفُۢۚ بَل لَّعَنَهُمُ ٱللَّهُ بِكُفۡرِهِمۡ فَقَلِيلࣰ ا مَّا يُؤۡمِنُونَ','اور کہتے ہیں، ہمارے دل پردے میں ہیں۔ (نہیں) بلکہ الله نے ان کے کفر کے سبب ان پر لعنت کر رکھی ہے۔ پس یہ تھوڑے ہی پر ایمان لاتے ہیں','They say, “Our hearts are unreceptive!” In fact, Allah has condemned them for their disbelief. They have but little faith','और कहने लगे कि हमारे दिलों पर ग़िलाफ चढ़ा हुआ है (ऐसा नहीं) बल्कि उनके कुफ्र की वजह से खुदा ने उनपर लानत की है पस कम ही लोग ईमान लाते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,89,'Al-Baqara','وَلَمَّا جَآءَهُمۡ كِتَٰبࣱ مِّنۡ عِندِ ٱللَّهِ مُصَدِّقࣱ لِّمَا مَعَهُمۡ وَكَانُواْ مِن قَبۡلُ يَسۡتَفۡتِحُونَ عَلَى ٱلَّذِينَ كَفَرُواْ فَلَمَّا جَآءَهُم مَّا عَرَفُواْ كَفَرُواْ بِهِۦۚ فَلَعۡنَةُ ٱللَّهِ عَلَى ٱلۡكَٰفِرِينَ','اور جب الله کے ہاں سے ان کے پاس کتاب آئی جو ان کی (آسمانی) کتاب کی بھی تصدیق کرتی ہے، اور وہ پہلے (ہمیشہ) کافروں پر فتح مانگا کرتے تھے، تو جس چیز کو وہ خوب پہچانتے تھے، جب ان کے پاس آپہنچی تو اس سے کافر ہو گئے۔ پس کافروں پر الله کی لعنت','Although they used to pray for victory ˹by means of the Prophet˺ over the polytheists, when there came to them a Book from Allah which they recognized, confirming the Scripture they had ˹in their hands˺, they rejected it. So may Allah’s condemnation be upon the disbelievers','और जब उनके पास खुदा की तरफ़ से किताब (कुरान आई और वह उस किताब तौरेत) की जो उन के पास तसदीक़ भी करती है। और उससे पहले (इसकी उम्मीद पर) काफ़िरों पर फतेहयाब होने की दुआएँ माँगते थे पस जब उनके पास वह चीज़ जिसे पहचानते थे आ गई तो लगे इन्कार करने पस काफ़िरों पर खुदा की लानत है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,90,'Al-Baqara','بِئۡسَمَا ٱشۡتَرَوۡاْ بِهِۦٓ أَنفُسَهُمۡ أَن يَكۡفُرُواْ بِمَآ أَنزَلَ ٱللَّهُ بَغۡيًا أَن يُنَزِّلَ ٱللَّهُ مِن فَضۡلِهِۦ عَلَىٰ مَن يَشَآءُ مِنۡ عِبَادِهِۦۖ فَبَآءُو بِغَضَبٍ عَلَىٰ غَضَبࣲۚ وَلِلۡكَٰفِرِينَ عَذَابࣱ مُّهِينࣱ‏','جس چیز کے بدلے انہوں نے اپنے تئیں بیچ ڈالا، وہ بہت بری ہے، یعنی اس جلن سے کہ خدا اپنے بندوں میں جس پر چاہتا ہے، اپنی مہربانی سے نازل فرماتا ہے۔ خدا کی نازل کی ہوئی کتاب سے کفر کرنے لگے تو وہ (اس کے) غضب بالائے غضب میں مبتلا ہو گئے۔ اور کافروں کے لیے ذلیل کرنے والا عذاب ہے','Miserable is the price they have sold their souls for—denying Allah’s revelation and resenting Allah for granting His grace to whoever He wills of His servants! They have earned wrath upon wrath. And such disbelievers will suffer a humiliating punishment','क्या ही बुरा है वह काम जिसके मुक़ाबले में (इतनी बात पर) वह लोग अपनी जानें बेच बैठे हैं कि खुदा अपने बन्दों से जिस पर चाहे अपनी इनायत से किताब नाज़िल किया करे इस रश्क से जो कुछ खुदा ने नाज़िल किया है सबका इन्कार कर बैठे पस उन पर ग़ज़ब पर ग़ज़ब टूट पड़ा और काफ़िरों के लिए (बड़ी) रूसवाई का अज़ाब है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,91,'Al-Baqara','وَإِذَا قِيلَ لَهُمۡ ءَامِنُواْ بِمَآ أَنزَلَ ٱللَّهُ قَالُواْ نُؤۡمِنُ بِمَآ أُنزِلَ عَلَيۡنَا وَيَكۡفُرُونَ بِمَا وَرَآءَهُۥ وَهُوَ ٱلۡحَقُّ مُصَدِّقࣰ ا لِّمَا مَعَهُمۡۗ قُلۡ فَلِمَ تَقۡتُلُونَ أَنۢبِيَآءَ ٱللَّهِ مِن قَبۡلُ إِن كُنتُم مُّؤۡمِنِينَ','اور جب ان سے کہا جاتا ہے کہ جو (کتاب) خدا نے (اب) نازل فرمائی ہے، اس کو مانو۔ تو کہتے ہیں کہ جو کتاب ہم پر (پہلے) نازل ہو چکی ہے، ہم تو اسی کو مانتے ہیں۔ (یعنی) یہ اس کے سوا کسی اور (کتاب) کو نہیں مانتے، حالانکہ وہ (سراسر) سچی ہے اور جو ان کی (آسمانی) کتاب ہے، اس کی بھی تصدیق کرتی ہے۔ (ان سے) کہہ دو کہ اگر تم صاحبِ ایمان ہوتے تو الله کے پیغمبروں کو پہلے ہی کیوں قتل کیا کرتے','When it is said to them: “Believe in what Allah has revealed,” they reply, “We only believe in what was sent down to us,” and they deny what came afterwards, though it is the truth confirming their own Scriptures! Ask ˹them, O Prophet˺, “Why then did you kill Allah’s prophets before, if you are ˹truly˺ believers?”','और जब उनसे कहा गया कि (जो क़ुरान) खुदा ने नाज़िल किया है उस पर ईमान लाओ तो कहने लगे कि हम तो उसी किताब (तौरेत) पर ईमान लाए हैं जो हम पर नाज़िल की गई थी और उस किताब (कुरान) को जो उसके बाद आई है नहीं मानते हैं हालाँकि वह (क़ुरान) हक़ है और उस किताब (तौरेत) की जो उनके पास है तसदीक़ भी करती है मगर उस किताब कुरान का जो उसके बाद आई है इन्कार करते हैं (ऐ रसूल) उनसे ये तो पूछो कि तुम (तुम्हारे बुर्जुग़) अगर ईमानदार थे तो फिर क्यों खुदा के पैग़म्बरों का साबिक़ क़त्ल करते थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,92,'Al-Baqara','۞وَلَقَدۡ جَآءَكُم مُّوسَىٰ بِٱلۡبَيِّنَٰتِ ثُمَّ ٱتَّخَذۡتُمُ ٱلۡعِجۡلَ مِنۢ بَعۡدِهِۦ وَأَنتُمۡ ظَٰلِمُونَ','اور موسیٰ تمہارے پاس کھلے ہوئے معجزات لے کر آئے تو تم ان کے (کوہِ طور جانے کے) بعد بچھڑے کو معبود بنا بیٹھے اور تم (اپنے ہی حق میں) ظلم کرتے تھے','Indeed, Moses came to you with clear proofs, then you worshipped the calf in his absence, acting wrongfully','और तुम्हारे पास मूसा तो वाज़ेए व रौशन मौजिज़े लेकर आ ही चुके थे फिर भी तुमने उनके बाद बछड़े को खुदा बना ही लिया और उससे तुम अपने ही ऊपर ज़ुल्म करने वाले थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,93,'Al-Baqara','وَإِذۡ أَخَذۡنَا مِيثَٰقَكُمۡ وَرَفَعۡنَا فَوۡقَكُمُ ٱلطُّورَ خُذُواْ مَآ ءَاتَيۡنَٰكُم بِقُوَّةࣲ وَٱسۡمَعُواْۖ قَالُواْ سَمِعۡنَا وَعَصَيۡنَا وَأُشۡرِبُواْ فِي قُلُوبِهِمُ ٱلۡعِجۡلَ بِكُفۡرِهِمۡۚ قُلۡ بِئۡسَمَا يَأۡمُرُكُم بِهِۦٓ إِيمَٰنُكُمۡ إِن كُنتُم مُّؤۡمِنِينَ','اور جب ہم نے تم (لوگوں) سے عہد واثق لیا اور کوہ طور کو تم پر اٹھا کھڑا کیا (اور حکم دیا کہ) جو (کتاب) ہم نے تم کو دی ہے، اس کو زور سے پکڑو اور جو تمہیں حکم ہوتا ہے (اس کو) سنو تو وہ (جو تمہارے بڑے تھے) کہنے لگے کہ ہم نے سن تو لیا لیکن مانتے نہیں۔ اور ان کے کفر کے سبب بچھڑا (گویا) ان کے دلوں میں رچ گیا تھا۔ (اے پیغمبر ان سے) کہہ دو کہ اگر تم مومن ہو تو تمہارا ایمان تم کو بری بات بتاتا ہے','And when We took your covenant and raised the mountain above you ˹saying˺, “Hold firmly to that ˹Scripture˺ which We have given you and obey,” they answered, “We hear and disobey.” The love of the calf was rooted in their hearts because of their disbelief. Say, ˹O Prophet,˺ “How evil is what your ˹so-called˺ belief prompts you to do, if you ˹actually˺ believe ˹in the Torah˺!”','और (वह वक्त याद करो) जब हमने तुमसे अहद लिया और (क़ोहे) तूर को (तुम्हारी उदूले हुक्मी से) तुम्हारे सर पर लटकाया और (हमने कहा कि ये किताब तौरेत) जो हमने दी है मज़बूती से लिए रहो और (जो कुछ उसमें है) सुनो तो कहने लगे सुना तो (सही लेकिन) हम इसको मानते नहीं और उनकी बेईमानी की वजह से (गोया) बछड़े की उलफ़त घोल के उनके दिलों में पिला दी गई (ऐ रसूल) उन लोगों से कह दो कि अगर तुम ईमानदार थे तो तुमको तुम्हारा ईमान क्या ही बुरा हुक्म करता था');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,94,'Al-Baqara','قُلۡ إِن كَانَتۡ لَكُمُ ٱلدَّارُ ٱلۡأٓخِرَةُ عِندَ ٱللَّهِ خَالِصَةࣰ مِّن دُونِ ٱلنَّاسِ فَتَمَنَّوُاْ ٱلۡمَوۡتَ إِن كُنتُمۡ صَٰدِقِينَ','کہہ دو کہ اگر آخرت کا گھر اور لوگوں (یعنی مسلمانوں) کے لیے نہیں اور خدا کے نزدیک تمہارے ہی لیے مخصوص ہے تو اگر سچے ہو تو موت کی آرزو تو کرو','Say, ˹O Prophet,˺ “If the ˹eternal˺ Home of the Hereafter with Allah is exclusively for you ˹Israelites˺ out of all humanity, then wish for death if what you say is true!”','(ऐ रसूल) इन लोगों से कह दो कि अगर खुदा के नज़दीक आख़ेरत का घर (बेहिश्त) ख़ास तुम्हारे वास्ते है और लोगों के वासते नहीं है पस अगर तुम सच्चे हो तो मौत की आरजू क़रो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,95,'Al-Baqara','وَلَن يَتَمَنَّوۡهُ أَبَدَۢا بِمَا قَدَّمَتۡ أَيۡدِيهِمۡۚ وَٱللَّهُ عَلِيمُۢ بِٱلظَّٰلِمِينَ','لیکن ان اعمال کی وجہ سے، جو ان کے ہاتھ آگے بھیج چکے ہیں، یہ کبھی اس کی آرزو نہیں کریں گے، اور خدا ظالموں سے (خوب) واقف ہے','But they will never wish for that because of what their hands have done. And Allah has ˹perfect˺ knowledge of the wrongdoers','(ताकि जल्दी बेहिश्त में जाओ) लेकिन वह उन आमाले बद की वजह से जिनको उनके हाथों ने पहले से आगे भेजा है हरगिज़ मौत की आरज़ू न करेंगे और खुदा ज़ालिमों से खूब वाक़िफ है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,96,'Al-Baqara','وَلَتَجِدَنَّهُمۡ أَحۡرَصَ ٱلنَّاسِ عَلَىٰ حَيَوٰةࣲ وَمِنَ ٱلَّذِينَ أَشۡرَكُواْۚ يَوَدُّ أَحَدُهُمۡ لَوۡ يُعَمَّرُ أَلۡفَ سَنَةࣲ وَمَا هُوَ بِمُزَحۡزِحِهِۦ مِنَ ٱلۡعَذَابِ أَن يُعَمَّرَۗ وَٱللَّهُ بَصِيرُۢ بِمَا يَعۡمَلُونَ','بلکہ ان کو تم اور لوگوں سے زندگی کے کہیں حریص دیکھو گے، یہاں تک کہ مشرکوں سے بھی۔ ان میں سے ہر ایک یہی خواہش کرتا ہے کہ کاش وہ ہزار برس جیتا رہے، مگر اتنی لمبی عمر اس کو مل بھی جائے تو اسے عذاب سے تو نہیں چھڑا سکتی۔ اور جو کام یہ کرتے ہیں، خدا ان کو دیکھ رہا ہے','You will surely find them clinging to life more eagerly than any other people, even more than polytheists. Each one of them wishes to live a thousand years. But even if they were to live that long, it would not save them from the punishment. And Allah is All-Seeing of what they do','और (ऐ रसूल) तुम उन ही को ज़िन्दगी का सबसे ज्यादा हरीस पाओगे और मुशरिक़ों में से हर एक शख्स चाहता है कि काश उसको हज़ार बरस की उम्र दी जाती हालाँकि अगर इतनी तूलानी उम्र भी दी जाए तो वह ख़ुदा के अज़ाब से छुटकारा देने वाली नहीं, और जो कुछ वह लोग करते हैं खुदा उसे देख रहा है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,97,'Al-Baqara','قُلۡ مَن كَانَ عَدُوࣰّ ا لِّـجِبۡرِيلَ فَإِنَّهُۥ نَزَّلَهُۥ عَلَىٰ قَلۡبِكَ بِإِذۡنِ ٱللَّهِ مُصَدِّقࣰ ا لِّمَا بَيۡنَ يَدَيۡهِ وَهُدࣰ ى وَبُشۡرَىٰ لِلۡمُؤۡمِنِينَ','کہہ دو کہ جو شخص جبرئیل کا دشمن ہو (اس کو غصے میں مر جانا چاہیئے) اس نے تو (یہ کتاب) خدا کے حکم سے تمہارے دل پر نازل کی ہے جو پہلی کتابوں کی تصدیق کرتی ہے، اور ایمان والوں کے لیے ہدایت اور بشارت ہے','Say, ˹O Prophet,˺ “Whoever is an enemy of Gabriel should know that he revealed this ˹Quran˺ to your heart by Allah’s Will, confirming what came before it—a guide and good news for the believers.”','(ऐ रसूल उन लोगों से) कह दो कि जो जिबरील का दुशमन है (उसका खुदा दुशमन है) क्योंकि उस फ़रिश्ते ने खुदा के हुक्म से (इस कुरान को) तुम्हारे दिल पर डाला है और वह उन किताबों की भी तसदीक करता है जो (पहले नाज़िल हो चुकी हैं और सब) उसके सामने मौजूद हैं और ईमानदारों के वास्ते खुशख़बरी है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,98,'Al-Baqara','مَن كَانَ عَدُوࣰّ ا لِّلَّهِ وَمَلَٰٓئِكَتِهِۦ وَرُسُلِهِۦ وَجِبۡرِيلَ وَمِيكَىٰلَ فَإِنَّ ٱللَّهَ عَدُوࣱّ لِّلۡكَٰفِرِينَ','جو شخص خدا کا اور اس کے فرشتوں کا اور اس کے پیغمبروں کا اور جبرئیل اور میکائیل کا دشمن ہو تو ایسے کافروں کا خدا دشمن ہے','Whoever is an enemy of Allah, His angels, His messengers, Gabriel, and Michael, then ˹let them know that˺ Allah is certainly the enemy of the disbelievers','जो शख्स ख़ुदा और उसके फरिश्तों और उसके रसूलों और (ख़ासकर) जिबराईल व मीकाइल का दुशमन हो तो बेशक खुदा भी (ऐसे) काफ़िरों का दुश्मन है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,99,'Al-Baqara','وَلَقَدۡ أَنزَلۡنَآ إِلَيۡكَ ءَايَٰتِۭ بَيِّنَٰتࣲۖ وَمَا يَكۡفُرُ بِهَآ إِلَّا ٱلۡفَٰسِقُونَ','اور ہم نے تمہارے پاس سلجھی ہوئی آیتیں ارسال فرمائی ہیں، اور ان سے انکار وہی کرتے ہیں جو بدکار ہیں','Indeed, We have sent down to you ˹O Prophet˺ clear revelations. ˹But˺ none will deny them except the rebellious','और (ऐ रसूल) हमने तुम पर ऐसी निशानियाँ नाज़िल की हैं जो वाजेए और रौशन हैं और ऐसे नाफरमानों के सिवा उनका कोई इन्कार नहीं कर सकता');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,100,'Al-Baqara','أَوَكُلَّمَا عَٰهَدُواْ عَهۡدࣰ ا نَّبَذَهُۥ فَرِيقࣱ مِّنۡهُمۚ بَلۡ أَكۡثَرُهُمۡ لَا يُؤۡمِنُونَ','ان لوگوں نے جب (خدا سے) عہد واثق کیا تو ان میں سے ایک فریق نے اس کو (کسی چیز کی طرح) پھینک دیا۔ حقیقت یہ ہے کہ ان میں اکثر بے ایمان ہیں','Why is it that every time they make a covenant, a group of them casts it aside? In fact, most of them do not believe','और उनकी ये हालत है कि जब कभी कोई अहद किया तो उनमें से एक फरीक़ ने तोड़ डाला बल्कि उनमें से अक्सर तो ईमान ही नहीं रखते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,101,'Al-Baqara','وَلَمَّا جَآءَهُمۡ رَسُولࣱ مِّنۡ عِندِ ٱللَّهِ مُصَدِّقࣱ لِّمَا مَعَهُمۡ نَبَذَ فَرِيقࣱ مِّنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ كِتَٰبَ ٱللَّهِ وَرَآءَ ظُهُورِهِمۡ كَأَنَّهُمۡ لَا يَعۡلَمُونَ','اور جب ان کے پاس الله کی طرف سے پیغمبر (آخرالزماں) آئے، اور وہ ان کی (آسمانی) کتاب کی بھی تصدیق کرتے ہیں تو جن لوگوں کو کتاب دی گئی تھی، ان میں سے ایک جماعت نے خدا کی کتاب کو پیٹھ پیچھے پھینک دیا، گویا وہ جانتے ہی نہیں','Now, when a messenger from Allah has come to them—confirming their own Scriptures—some of the People of the Book cast the Book of Allah behind their backs as if they did not know','और जब उनके पास खुदा की तरफ से रसूल (मोहम्मद) आया और उस किताब (तौरेत) की जो उनके पास है तसदीक़ भी करता है तो उन अहले किताब के एक गिरोह ने किताबे खुदा को अपने पसे पुश्त फेंक दिया गोया वह लोग कुछ जानते ही नहीं और उस मंत्र के पीछे पड़ गए');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,102,'Al-Baqara','وَٱتَّبَعُواْ مَا تَتۡلُواْ ٱلشَّيَٰطِينُ عَلَىٰ مُلۡكِ سُلَيۡمَٰنَۖ وَمَا كَفَرَ سُلَيۡمَٰنُ وَلَٰكِنَّ ٱلشَّيَٰطِينَ كَفَرُواْ يُعَلِّمُونَ ٱلنَّاسَ ٱلسِّحۡرَ وَمَآ أُنزِلَ عَلَى ٱلۡمَلَكَيۡنِ بِبَابِلَ هَٰرُوتَ وَمَٰرُوتَۚ وَمَا يُعَلِّمَانِ مِنۡ أَحَدٍ حَتَّىٰ يَقُولَآ إِنَّمَا نَحۡنُ فِتۡنَةࣱ فَلَا تَكۡفُرۡۖ فَيَتَعَلَّمُونَ مِنۡهُمَا مَا يُفَرِّقُونَ بِهِۦ بَيۡنَ ٱلۡمَرۡءِ وَزَوۡجِهِۦۚ وَمَا هُم بِضَآرِّينَ بِهِۦ مِنۡ أَحَدٍ إِلَّا بِإِذۡنِ ٱللَّهِۚ وَيَتَعَلَّمُونَ مَا يَضُرُّهُمۡ وَلَا يَنفَعُهُمۡۚ وَلَقَدۡ عَلِمُواْ لَمَنِ ٱشۡتَرَىٰهُ مَا لَهُۥ فِي ٱلۡأٓخِرَةِ مِنۡ خَلَٰقࣲۚ وَلَبِئۡسَ مَا شَرَوۡاْ بِهِۦٓ أَنفُسَهُمۡۚ لَوۡ كَانُواْ يَعۡلَمُونَ','اور ان (ہزلیات) کے پیچھے لگ گئے جو سلیمان کے عہدِ سلطنت میں شیاطین پڑھا کرتے تھے اور سلیمان نے مطلق کفر کی بات نہیں کی، بلکہ شیطان ہی کفر کرتے تھے کہ لوگوں کو جادو سکھاتے تھے۔ اور ان باتوں کے بھی (پیچھے لگ گئے) جو شہر بابل میں دو فرشتوں (یعنی) ہاروت اور ماروت پر اتری تھیں۔ اور وہ دونوں کسی کو کچھ نہیں سکھاتے تھے، جب تک یہ نہ کہہ دیتے کہ ہم تو (ذریعہٴ) آزمائش ہیں۔ تم کفر میں نہ پڑو۔ غرض لوگ ان سے (ایسا) جادو سیکھتے، جس سے میاں بیوی میں جدائی ڈال دیں۔ اور خدا کے حکم کے سوا وہ اس (جادو) سے کسی کا کچھ بھی نہیں بگاڑ سکتے تھے۔ اور کچھ ایسے (منتر) سیکھتے جو ان کو نقصان ہی پہنچاتے اور فائدہ کچھ نہ دیتے۔ اور وہ جانتے تھے کہ جو شخص ایسی چیزوں (یعنی سحر اور منتر وغیرہ) کا خریدار ہوگا، اس کا آخرت میں کچھ حصہ نہیں۔ اور جس چیز کے عوض انہوں نے اپنی جانوں کو بیچ ڈالا، وہ بری تھی۔ کاش وہ (اس بات کو) جانتے','They ˹instead˺ followed the magic promoted by the devils during the reign of Solomon. Never did Solomon disbelieve, rather the devils disbelieved. They taught magic to the people, along with what had been revealed to the two angels, Hârût and Mârût, in Babylon. The two angels never taught anyone without saying, “We are only a test ˹for you˺, so do not abandon ˹your˺ faith.” Yet people learned ˹magic˺ that caused a rift ˹even˺ between husband and wife; although their magic could not harm anyone except by Allah’s Will. They learned what harmed them and did not benefit them—although they already knew that whoever buys into magic would have no share in the Hereafter. Miserable indeed was the price for which they sold their souls, if only they knew','जिसको सुलेमान के ज़माने की सलतनत में शयातीन जपा करते थे हालाँकि सुलेमान ने कुफ्र नहीं इख़तेयार किया लेकिन शैतानों ने कुफ्र एख़तेयार किया कि वह लोगों को जादू सिखाया करते थे और वह चीज़ें जो हारूत और मारूत दोनों फ़रिश्तों पर बाइबिल में नाज़िल की गई थी हालाँकि ये दोनों फ़रिश्ते किसी को सिखाते न थे जब तक ये न कह देते थे कि हम दोनों तो फ़क़त (ज़रियाए आज़माइश) है पस तो (इस पर अमल करके) बेईमान न हो जाना उस पर भी उनसे वह (टोटके) सीखते थे जिनकी वजह से मिया बीवी में तफ़रक़ा डालते हालाँकि बग़ैर इज्ने खुदावन्दी वह अपनी इन बातों से किसी को ज़रर नहीं पहुँचा सकते थे और ये लोग ऐसी बातें सीखते थे जो खुद उन्हें नुक़सान पहुँचाती थी और कुछ (नफा) पहुँचाती थी बावजूद कि वह यक़ीनन जान चुके थे कि जो शख्स इन (बुराईयों) का ख़रीदार हुआ वह आख़िरत में बेनसीब हैं और बेशुबह (मुआवज़ा) बहुत ही बड़ा है जिसके बदले उन्होंने अपनी जानों को बेचा काश (उसे कुछ) सोचे समझे होते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,103,'Al-Baqara','وَلَوۡ أَنَّهُمۡ ءَامَنُواْ وَٱتَّقَوۡاْ لَمَثُوبَةࣱ مِّنۡ عِندِ ٱللَّهِ خَيۡرࣱۚ لَّوۡ كَانُواْ يَعۡلَمُونَ','اور اگر وہ ایمان لاتے اور پرہیز گاری کرتے تو خدا کے ہاں سے بہت اچھا صلہ ملتا۔ اے کاش، وہ اس سے واقف ہوتے','If only they were faithful and mindful ˹of Allah˺, there would have been a better reward from Allah, if only they knew','और अगर वह ईमान लाते और जादू वग़ैरह से बचकर परहेज़गार बनते तो खुदा की दरगाह से जो सवाब मिलता वह उससे कहीं बेहतर होता काश ये लोग (इतना तो) समझते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,104,'Al-Baqara','يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَقُولُواْ رَٰعِنَا وَقُولُواْ ٱنظُرۡنَا وَٱسۡمَعُواْۗ وَلِلۡكَٰفِرِينَ عَذَابٌ أَلِيمࣱ‏','اے اہل ایمان! (گفتگو کے وقت پیغمبرِ خدا سے) راعنا نہ کہا کرو۔ انظرنا کہا کرو۔ اور خوب سن رکھو، اور کافروں کے لیے دکھ دینے والا عذاب ہے','O believers! Do not say, “Râ’ina.” [Herd us!] But say, “Unẓurna,” [Tend to us!] and listen ˹attentively˺. And the disbelievers will suffer a painful punishment','ऐ ईमानवालों तुम (रसूल को अपनी तरफ मुतावज्जे करना चाहो तो) रआना (हमारी रिआयत कर) न कहा करो बल्कि उनज़ुरना (हम पर नज़रे तवज्जो रख) कहा करो और (जी लगाकर) सुनते रहो और काफिरों के लिए दर्दनाक अज़ाब है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,105,'Al-Baqara','مَّا يَوَدُّ ٱلَّذِينَ كَفَرُواْ مِنۡ أَهۡلِ ٱلۡكِتَٰبِ وَلَا ٱلۡمُشۡرِكِينَ أَن يُنَزَّلَ عَلَيۡكُم مِّنۡ خَيۡرࣲ مِّن رَّبِّكُمۡۚ وَٱللَّهُ يَخۡتَصُّ بِرَحۡمَتِهِۦ مَن يَشَآءُۚ وَٱللَّهُ ذُو ٱلۡفَضۡلِ ٱلۡعَظِيمِ','جو لوگ کافر ہیں، اہل کتاب یا مشرک وہ اس بات کو پسند نہیں کرتے کہ تم پر تمہارے پروردگار کی طرف سے خیر (وبرکت) نازل ہو۔ اور خدا تو جس کو چاہتا ہے، اپنی رحمت کے ساتھ خاص کر لیتا ہے اور خدا بڑے فضل کا مالک ہے','The disbelievers from the People of the Book and the polytheists would not want you to receive any blessing from your Lord, but Allah selects whoever He wills for His mercy. And Allah is the Lord of infinite bounty','ऐ रसूल अहले किताब में से जिन लोगों ने कुफ्र इख़तेयार किया वह और मुशरेकीन ये नहीं चाहते हैं कि तुम पर तुम्हारे परवरदिगार की तरफ से भलाई (वही) नाज़िल की जाए और (उनका तो इसमें कुछ इजारा नहीं) खुदा जिसको चाहता है अपनी रहमत के लिए ख़ास कर लेता है और खुदा बड़ा फज़ल (करने) वाला है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (2,106,'Al-Baqara','۞مَا نَنسَخۡ مِنۡ ءَايَةٍ أَوۡ نُنسِهَا نَأۡتِ بِخَيۡرࣲ مِّنۡهَآ أَوۡ مِثۡلِهَآۗ أَلَمۡ تَعۡلَمۡ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءࣲ قَدِيرٌ','ہم جس آیت کو منسوخ کر دیتے یا اسے فراموش کرا دیتے ہیں تو اس سے بہتر یا ویسی ہی اور آیت بھیج دیتے ہیں۔ کیا تم نہیں جانتے کہ خدا ہر بات پر قادر ہے','If We ever abrogate a verse or cause it to be forgotten, We replace it with a better or similar one. Do you not know that Allah is Most Capable of everything','(ऐ रसूल) हम जब कोई आयत मन्सूख़ करते हैं या तुम्हारे ज़ेहन से मिटा देते हैं तो उससे बेहतर या वैसी ही (और) नाज़िल भी कर देते हैं क्या तुम नहीं जानते कि बेशुबहा खुदा हर चीज़ पर क़ादिर है');
